{"command": "cd /tmp/p && python3 - <<'EOF'
def jaro(s1,s2):
    if s1==s2: return 1.0
    l1,l2=len(s1),len(s2)
    if l1==0 or l2==0: return 0.0
    md = max(l1,l2)//2 - 1
    if md<0: md=0
    f1=[False]*l1; f2=[False]*l2; m=0
    for i in range(l1):
        lo=max(0,i-md); hi=min(l2,i+md+1)
        for j in range(lo,hi):
            if not f2[j] and s1[i]==s2[j]:
                f1[i]=True; f2[j]=True; m+=1; break
    if m==0: return 0.0
    k=0; t=0
    for i in range(l1):
        if f1[i]:
            while not f2[k]: k+=1
            if s1[i]!=s2[k]: t+=1
            k+=1
    return (m/l1 + m/l2 + (m-t/2)/m)/3
def jw(s1,s2):
    j=jaro(s1,s2)
    if j<0.7: return j
    p=0
    for a,b in zip(s1,s2):
        if a!=b: break
        p+=1
    return j + 0.1*p*(1-j)
names=['init-config','init','generate','build','parse','test','version','fuzz','query','highlight','tags','playground','dump-languages','complete']
tests=['b','f','g','i','p','q','t','hi','pg','gen','comp','play','ge','bu','te','hig','com','pla','v','d','c','h','tag','dump','ver','init']
for w in tests:
    scores=sorted(((jw(w,n),n) for n in names), reverse=True)[:3]
    print(f"{w:10s} {scores}")
EOF"}

