{"command": "cd /tmp/p && python3 - <<'EOF'
import subprocess, re, collections
names=['init-config','init','generate','build','parse','test','version','fuzz','query','highlight','tags','playground','dump-languages','complete']
al = collections.defaultdict(set)
def probe(w):
    p = subprocess.run(['/tmp/p/xprogx', w, '--nonexistent'], capture_output=True, text=True)
    m = re.search(r"tip: (?:a|some) similar subcommands? exist[s]?: (.*)", p.stderr)
    if m:
        cands = re.findall(r"'([^']*)'", m.group(1))
        for c in cands: al[c].add(w)
    # usage line reveals dispatch
    for l in p.stderr.split('\n'):
        if l.startswith('Usage: xprogx '):
            parts = l.split(' ')
            if len(parts)>2 and parts[2] != '<COMMAND>':
                al[parts[2]].add('USED:' + w)
for n in names:
    for i in range(1, len(n)+1):
        probe(n[:i])
for k in sorted(al): print(k, sorted(al[k]))
EOF"}

