"""A hand written argument parser that reproduces the behaviour of the
clap based command line interface of the reference tool.

The parser is intentionally minimal: it only knows about the shapes that the
reference implementation uses (flags, single values, optional values and
variadic values) and it reproduces the exact wording of clap's error
messages.
"""

import os
import sys


def jaro(a, b):
    """Jaro similarity, matching the semantics used by the reference tool
    when it produces "did you mean" hints."""
    la, lb = len(a), len(b)
    if la == 0 and lb == 0:
        return 1.0
    if la == 0 or lb == 0:
        return 0.0
    if la == 1 and lb == 1:
        return 1.0 if a == b else 0.0
    search_range = max(la, lb) // 2 - 1
    if search_range < 0:
        search_range = 0
    b_taken = [False] * lb
    a_taken = [False] * la
    matches = 0
    for i in range(la):
        lo = max(0, i - search_range)
        hi = min(lb, i + search_range + 1)
        for j in range(lo, hi):
            if not b_taken[j] and a[i] == b[j]:
                a_taken[i] = True
                b_taken[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    transpositions = 0
    k = 0
    for i in range(la):
        if not a_taken[i]:
            continue
        while not b_taken[k]:
            k += 1
        if a[i] != b[k]:
            transpositions += 1
        k += 1
    return (matches / la + matches / lb + (matches - transpositions / 2) / matches) / 3


def did_you_mean(word, candidates):
    """Candidates with a jaro similarity above 0.7, sorted by similarity."""
    scored = [(jaro(word, c), c) for c in candidates]
    scored = [s for s in scored if s[0] > 0.7]
    scored.sort(key=lambda item: item[0])
    return [c for _, c in scored]


class Arg:
    def __init__(self, long=None, short=None, value_name=None, variadic=False,
                 optional_value=False, required=False, possible=None,
                 env=None, default=None, repeats=False):
        self.long = long
        self.short = short
        self.value_name = value_name
        self.variadic = variadic
        self.optional_value = optional_value
        self.required = required
        self.possible = possible
        self.env = env
        self.default = default
        self.repeats = repeats

    # ------------------------------------------------------------------
    def is_flag(self):
        return self.value_name is None

    def spec(self):
        if self.is_flag():
            return '--' + self.long
        if self.variadic:
            return '--%s <%s>...' % (self.long, self.value_name)
        if self.optional_value:
            return '--%s [<%s>]' % (self.long, self.value_name)
        return '--%s <%s>' % (self.long, self.value_name)

    def usage(self):
        return self.spec()


