    def __init__(self, name, required=False, variadic=False):
        self.name = name
        self.required = required
        self.variadic = variadic

    def usage(self):
        if self.required:
            return '<%s>' % self.name
        return '[%s]...' % self.name if self.variadic else '[%s]' % self.name

    def usage_full(self):
        if self.variadic:
            return ('<%s>...' if self.required else '[%s]...') % self.name
        return ('<%s>' if self.required else '[%s]') % self.name


