    def __init__(self, name, aliases=(), args=(), positionals=(),
                 usage_extra='', help_short=None, help_long=None):
        self.name = name
        self.aliases = list(aliases)
        self.args = list(args)
        self.positionals = list(positionals)
        self.usage_extra = usage_extra
        self.help_short = help_short
        self.help_long = help_long

    # ------------------------------------------------------------------
    def usage_full(self, prog):
        return '%s %s' % (self.name, self.usage_extra) if self.usage_extra \
            else self.name

    def usage_with(self, prog, used):
        """Usage line when some arguments were already consumed."""
        if not used:
            return self.usage_full(prog)
        parts = [self.name] + [a.usage() for a in used]
        parts.extend(p.usage_full() for p in self.positionals)
        return ' '.join(parts)

    def by_long(self, name):
        for a in self.args:
            if a.long == name:
                return a
        return None

    def by_short(self, ch):
        for a in self.args:
            if a.short == ch:
                return a
        return None


class CliError(Exception):
    def __init__(self, message, usage=None, tip=None, possible=None,
                 extra=None, code=2):
        self.message = message
        self.usage = usage
        self.tip = tip
        self.possible = possible
        self.extra = extra
        self.code = code

    def render(self, prog):
        out = []
        out.append('error: ' + self.message)
        if self.extra:
            for line in self.extra:
                out.append(line)
        if self.possible:
            out.append('  [possible values: %s]' % ', '.join(self.possible))
        if self.tip:
            out.append('')
            for line in self.tip:
                out.append('  ' + line)
        if self.usage is not None:
            out.append('')
            out.append('Usage: ' + self.usage)
        out.append('')
        out.append("For more information, try '--help'.")
        return '\n'.join(out)


class Parsed:
    def __init__(self):
        self.flags = set()
        self.values = {}
        self.lists = {}
        self.positionals = []


class Parser:
    """Parses the argument list of a single subcommand."""

    def __init__(self, cmd, prog):
        self.cmd = cmd
        self.prog = prog
        self.parsed = Parsed()
        self.used = []
        self.out = sys.stderr

    # ------------------------------------------------------------------
    def error(self, *args, **kwargs):
        raise CliError(*args, **kwargs)

    def unknown(self, token):
        # did we get this far with already parsed arguments?
        tip = []
        suggestion = did_you_mean_for_arg(self.cmd, token)
        used = list(self.used)
        if suggestion is not None:
            tip.append("a similar argument exists: '%s'" % suggestion)
            arg = self.cmd.by_long(suggestion[2:])
            if arg is not None:
                used.append(arg)
        else:
            tip.append("to pass '%s' as a value, use '-- %s'" % (token, token))
        self.error("unexpected argument '%s' found" % token,
                   usage=self.cmd.usage_with(self.prog, used), tip=tip)

    # ------------------------------------------------------------------
    def parse(self, tokens, help_cb, version_cb=None):
        idx = 0
        n = len(tokens)
        after_dd = False
        pos_index = 0
        while idx < n:
            tok = tokens[idx]
            idx += 1
            if after_dd:
                self.take_positional(tok)
                continue
            if tok == '--':
                after_dd = True
                continue
            if tok.startswith('--') and len(tok) > 2:
                self.parse_long(tok, tokens, idx, help_cb, version_cb)
                idx = self.idx
                continue
            if tok.startswith('-') and len(tok) > 1 and tok != '-':
                self.parse_short(tok, tokens, idx, help_cb, version_cb)
                idx = self.idx
                continue
            self.take_positional(tok)
        self.finish()

    # ------------------------------------------------------------------
    def parse_long(self, tok, tokens, idx, help_cb, version_cb):
        body = tok[2:]
        if '=' in body:
            name, _, value = body.partition('=')
        else:
            name, value = body, None
        if name == 'help':
            help_cb()
        if version_cb is not None and name == 'version':
            version_cb()
        arg = self.cmd.by_long(name)
        if arg is None:
            # A pending optional value?  clap treats a "--" token as a flag.
            self.unknown('--' + name)
        if arg.is_flag():
            if value is not None:
                self.error("unexpected value '%s' for '--%s' found; no more "
                           "were expected" % (value, arg.long),
                           usage=self.cmd.usage_with(
                               self.prog, self.mark_used(arg)),
                           tip=None)
            self.mark(arg)
            self.parsed.flags.add(arg.long)
            self.idx = idx
            return
        if arg.optional_value and value is None:
            # value may follow separated by a space
            self.mark(arg)
            if idx < len(tokens):
                nxt = tokens[idx]
                if nxt == '--' or not (nxt.startswith('-') and len(nxt) > 1):
                    self.parsed.values[arg.long] = nxt
                    self.idx = idx + 1
                    return
            self.idx = idx
            return
        if value is None:
            got, idx2 = self.take_value(arg, tokens, idx)
            self.idx = idx2
            self.assign(arg, got)
            return
        self.mark(arg)
        self.assign(arg, value)
        self.idx = idx

    # ------------------------------------------------------------------
    def parse_short(self, tok, tokens, idx, help_cb, version_cb):
        body = tok[1:]
        i = 0
        while i < len(body):
            ch = body[i]
            if ch == 'h':
                help_cb()
            if version_cb is not None and ch == 'V':
                version_cb()
            arg = self.cmd.by_short(ch)
            if arg is None:
                self.unknown('-' + ch)
            i += 1
            if arg.is_flag():
                self.mark(arg)
                self.parsed.flags.add(arg.long)
                if i < len(body) and body[i] == '=':
                    self.error("unexpected value '%s' for '--%s' found; no "
                               "more were expected" % (body[i + 1:], arg.long),
                               usage=self.cmd.usage_with(
                                   self.prog, self.mark_used(arg)),
                               tip=None)
                continue
            # takes a value
            rest = body[i:]
            if rest.startswith('='):
                rest = rest[1:]
            if rest:
                self.mark(arg)
                self.assign(arg, rest)
                self.idx = idx
                return
            got, idx2 = self.take_value(arg, tokens, idx)
            self.idx = idx2
            self.assign(arg, got)
            return
        self.idx = idx

    # ------------------------------------------------------------------
    def take_value(self, arg, tokens, idx):
        """Read the value of an option that expects one."""
        if idx >= len(tokens):
            self.error("a value is required for '%s' but none was supplied"
                       % arg.spec(), possible=arg.possible)
        nxt = tokens[idx]
        if nxt.startswith('-') and len(nxt) > 1 and nxt != '-':
            if nxt == '--':
                self.error("a value is required for '%s' but none was supplied"
                           % arg.spec(), possible=arg.possible)
            probe = self.cmd.by_long(nxt[2:].split('=')[0])
            if probe is None:
                probe = self.cmd.by_short(nxt[1])
            if probe is not None:
                self.error("a value is required for '%s' but none was supplied"
                           % arg.spec(), possible=arg.possible)
            self.unknown(nxt)
        self.mark(arg)
        return nxt, idx + 1

    # ------------------------------------------------------------------
    def mark(self, arg):
        if not arg.repeats and arg.long in (self.parsed.flags | set(
                self.parsed.values) | set(self.parsed.lists)):
            self.error("the argument '%s' cannot be used multiple times"
                       % arg.spec(), usage=self.cmd.usage_full(self.prog))
        if arg not in self.used:
            self.used.append(arg)
        return arg

    def mark_used(self, arg):
        if arg not in self.used:
            self.used.append(arg)
        return self.used

    def assign(self, arg, value):
        if arg.variadic:
            self.parsed.lists.setdefault(arg.long, []).append(value)
        else:
            self.parsed.values[arg.long] = value
        self.used.append(arg) if arg not in self.used else None

    # ------------------------------------------------------------------
    def take_positional(self, tok):
        pos = None
        if pos_index < len(self.cmd.positionals):
            pos = self.cmd.positionals[pos_index]
            if pos.variadic:
                self.parsed.positionals.append(tok)
                return
            pos_index += 1
            self.parsed.positionals.append(tok)
            return
        # no slot left
        self.unknown(tok)

    def finish(self):
        missing = []
        pos_index = 0
        n = len(self.cmd.positionals)
        supplied = len(self.parsed.positionals)
        for i, p in enumerate(self.cmd.positionals):
            if p.variadic:
                break
            if i >= supplied:
                if p.required:
                    missing.append(p.usage_full())
        if missing:
            self.error('the following required arguments were not provided:',
                       extra=['  ' + m for m in missing],
                       usage=self.cmd.usage_full(self.prog))
        # required options
        for a in self.cmd.args:
            if a.required and a.long not in self.parsed.values and \
                    a.long not in self.parsed.flags and \
                    a.long not in self.parsed.lists:
                missing.append(a.spec())
        if missing:
            self.error('the following required arguments were not provided:',
                       extra=['  ' + m for m in missing],
                       usage=self.cmd.usage_full(self.prog))


def did_you_mean_for_arg(cmd, token):
    """Suggest a similar flag name, mirroring the reference tool."""
    if not token.startswith('-'):
        return None
    names = [a.long for a in cmd.args]
    matches = did_you_mean(token.lstrip('-'), names)
    if not matches:
        return None
    return '--' + matches[-1]


def parse_command(cmd, argv, prog, help_cb, version_cb=None):
    parser = Parser(cmd, prog)
    parser.parse(argv, help_cb, version_cb)
    return parser.parsed
