def jaro(a, b):
    """Jaro similarity, matching the semantics used by the reference tool
    when it produces "did you mean" hints."""
    la, lb = len(a), len(b)
    if la == 0 and lb == 0:
        return 1.0
    if la == 0 or lb == 0:
        return 0.0
    if la == 1 and lb == 1:
        return 1.0 if a == b else 0.0
    search_range = max(la, lb) // 2 - 1
    if search_range < 0:
        search_range = 0
    b_taken = [False] * lb
    a_taken = [False] * la
    matches = 0
    for i in range(la):
        lo = max(0, i - search_range)
        hi = min(lb, i + search_range + 1)
        for j in range(lo, hi):
            if not b_taken[j] and a[i] == b[j]:
                a_taken[i] = True
                b_taken[j] = True
                matches += 1
