"""Entry point: argument dispatch for the command line interface."""

import os
import sys

from . import helptext, spec
from .argparse import did_you_mean, CliError, parse_command

VERSION = '0.27.0'


def subcommand_candidates():
    """The list of names that the top level command will match, in the order
    used to build "did you mean" hints."""
    out = []
    for name in spec.SUBCOMMAND_ORDER:
        for alias, target in spec.ALIASES.items():
            if target == name:
                out.append(alias)
        out.append(name)
    return out


def find_subcommand(word):
    if word in spec.ALIASES:
        return spec.ALIASES[word]
    for c in spec.COMMANDS:
        if c.name == word:
            return c.name
    return None


def print_help(prog, key, stream=sys.stdout):
    stream.write(helptext.get(key, prog))
    stream.write('\n')


def top_level_error(prog, word):
    matches = did_you_mean(word, subcommand_candidates())
    lines = ['error: unrecognized subcommand \'%s\'' % word]
    if matches:
        if len(matches) == 1:
            lines.append('')
            lines.append("  tip: a similar subcommand exists: '%s'" % matches[0])
        else:
            lines.append('')
            lines.append('  tip: some similar subcommands exist: ' +
                         ', '.join("'%s'" % m for m in matches))
    lines.append('')
    lines.append('Usage: %s <COMMAND>' % prog)
    lines.append('')
    lines.append("For more information, try '--help'.")
    return '\n'.join(lines)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    argv = list(argv)
    prog = os.path.basename(sys.argv[0]) if sys.argv[0] else 'tree-sitter'
    if not argv:
        print_help(prog, 'top_long', stream=sys.stderr)
        return 2

    first = argv[0]
    if first in ('-h', '--help'):
        print_help(prog, 'top_long')
        return 0
    if first in ('-V', '--version'):
        sys.stdout.write('tree-sitter %s\n' % VERSION)
        return 0

    target = find_subcommand(first)
    if target is None:
        if first.startswith('-'):
            sys.stderr.write('error: unexpected argument \'%s\' found\n\n'
                             'Usage: %s <COMMAND>\n\n'
                             "For more information, try '--help'.\n"
                             % (first, prog))
            return 2
        sys.stderr.write(top_level_error(prog, first) + '\n')
        return 2

    cmd = next(c for c in spec.COMMANDS if c.name == target)
    args = argv[1:]

    def help_cb(long=False):
        print_help(prog, cmd.help_long or cmd.name + '_long')
        raise _Help()

    class _Help(Exception):
        pass

    def cb_long():
        help_cb()

    def cb_short():
        print_help(prog, cmd.help_short or cmd.name + '_short')
        raise _Help()

    def real_help_cb():
        pass

    def help_flag_cb():
        print_help(prog, cmd.help_long or cmd.name + '_long')
        raise _Help()

    try:
        parsed = parse_command(cmd, args, prog, help_flag_cb)
    except CliError as err:
        sys.stderr.write(err.render(prog) + '\n')
        return err.code
    except _Help:
        return 0

    from . import dispatch
    return dispatch.run(cmd.name, parsed, prog)


if __name__ == '__main__':
    sys.exit(main())
