"""Tokenizer and recursive descent parser for a practical subset of
JavaScript."""

KEYWORDS = {
    'var', 'let', 'const', 'function', 'return', 'if', 'else', 'for', 'while',
    'do', 'break', 'continue', 'new', 'delete', 'typeof', 'instanceof', 'in',
    'of', 'this', 'null', 'true', 'false', 'void', 'throw', 'try', 'catch',
    'finally', 'switch', 'case', 'default', 'class', 'extends', 'super',
    'import', 'export', 'from', 'as', 'yield', 'await', 'async', 'static',
    'get', 'set',
}

PUNCT = [
    '>>>=', '...', '===', '!==', '**=', '<<=', '>>=', '&&=', '||=', '??=',
    '>>>', '<<', '>>', '<=', '>=', '==', '!=', '&&', '||', '??', '?.', '++',
    '--', '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=', '=>', '(', ')', '{',
    '}', '[', ']', ';', ',', '<', '>', '+', '-', '*', '/', '%', '&', '|', '^',
    '!', '~', '?', ':', '=', '.', '`',
]

ASSIGN_OPS = {'=', '+=', '-=', '*=', '/=', '%=', '**=', '<<=', '>>=', '>>>=',
              '&=', '|=', '^=', '&&=', '||=', '??='}

UNARY = {'-', '+', '!', '~', 'typeof', 'void', 'delete'}


class Token:
    __slots__ = ('kind', 'value', 'line', 'col')

    def __init__(self, kind, value, line, col):
        self.kind = kind
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self):
        return '%s(%r)' % (self.kind, self.value)


class JSyntaxError(Exception):
    def __init__(self, message, line=0, col=0):
        super().__init__(message)
        self.line = line
        self.col = col
        self.message = message


def is_ident_start(ch):
    return ch.isalpha() or ch == '_' or ch == '$' or ord(ch) > 127


def is_ident_char(ch):
    return ch.isalnum() or ch == '_' or ch == '$' or ord(ch) > 127


def tokenize(src):
    toks = []
    i = 0
    n = len(src)
    line = 1
    col = 1
    last_kind = None

    def advance(k):
        nonlocal i, line, col
        for _ in range(k):
            if src[i] == '\n':
                line += 1
                col = 1
            else:
                col += 1
            i += 1

    while i < n:
        ch = src[i]
        if ch in ' \t\r\n':
            advance(1)
            continue
        if ch == '/' and i + 1 < n and src[i + 1] == '/':
            j = src.find('\n', i)
            if j < 0:
                j = n
            advance(j - i)
            continue
        if ch == '/' and i + 1 < n and src[i + 1] == '*':
            j = src.find('*/', i + 2)
            if j < 0:
                j = n - 1
            for k in range(i, j + 2):
                if src[k] == '\n':
                    line += 1
                    col = 1
                else:
                    col += 1
            i = j + 2
            continue
        start_line, start_col = line, col
        # string literal
        if ch == '"' or ch == "'":
            quote = ch
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise JSyntaxError('unterminated string', line, col)
                c = src[j]
                if c == '\\':
                    nxt = src[j + 1] if j + 1 < n else ''
                    buf.append(escape_char(nxt, src, j))
                    j += 2 if nxt != 'u' and nxt != 'x' else 1
                    j = skip_escape(src, j + 1, buf)
                    continue
                if c == quote:
                    break
                buf.append(c)
                j += 1
            advance(j + 1 - i)
            toks.append(Token('str', ''.join(buf), start_line, start_col))
            last_kind = 'str'
            continue
        # template literal
        if ch == '`':
            parts, j, nline, ncol = scan_template(src, i)
            toks.append(Token('tmpl', parts, start_line, start_col))
            for k in range(i, j):
                if src[k] == '\n':
                    line += 1
                    col = 1
                else:
                    col += 1
            i = j
            last_kind = 'tmpl'
            continue
        # regex literal
        if ch == '/' and not regex_allowed(last_kind):
            j = i + 1
            in_class = False
            buf = []
            flags = ''
            while True:
                if j >= n:
                    raise JSyntaxError('unterminated regexp', line, col)
                c = src[j]
                if c == '\\':
                    buf.append(c)
                    buf.append(src[j + 1])
                    j += 2
                    continue
                if c == '[':
                    in_class = True
                elif c == ']':
                    in_class = False
                elif c == '/' and not in_class:
                    break
                buf.append(c)
                j += 1
            body = ''.join(buf)
            j += 1
            while j < n and (src[j].isalpha()):
                flags += src[j]
                j += 1
            advance(j - i)
            toks.append(Token('regex', (body, flags), start_line, start_col))
            last_kind = 'regex'
            continue
        # numbers
        if ch.isdigit() or (ch == '.' and i + 1 < n and src[i + 1].isdigit()):
            j = i
            if src.startswith('0x', i) or src.startswith('0X', i):
                j = i + 2
                while j < n and (src[j] in '0123456789abcdefABCDEF_'):
                    j += 1
                text = src[i:j]
                value = int(text.replace('_', ''), 16)
            elif src.startswith('0b', i) or src.startswith('0B', i):
                j = i + 2
                while j < n and src[j] in '01_':
                    j += 1
                value = int(src[i + 2:j].replace('_', ''), 2)
            elif src.startswith('0o', i) or src.startswith('0O', i):
                j = i + 2
                while j < n and src[j] in '01234567_':
                    j += 1
                value = int(src[i + 2:j].replace('_', ''), 8)
            else:
                seen_dot = False
                seen_exp = False
                while j < n:
                    c = src[j]
                    if c.isdigit():
                        j += 1
                    elif c == '.' and not seen_dot and not seen_exp:
                        seen_dot = True
                        j += 1
                    elif c in 'eE' and not seen_exp and j > i:
                        seen_exp = True
                        j += 1
                        if j < n and src[j] in '+-':
                            j += 1
                    elif c == 'n':
                        j += 1
                        break
                    else:
                        break
                text = src[i:j].rstrip('n')
                value = float(text) if ('.' in text or 'e' in text or 'E' in
                                        text) else int(text)
            advance(j - i)
            toks.append(Token('num', value, start_line, start_col))
            last_kind = 'num'
            continue
        # identifiers / keywords
        if is_ident_start(ch):
            j = i
            while j < n and is_ident_char(src[j]):
                j += 1
            word = src[i:j]
            advance(j - i)
            if word in KEYWORDS:
                toks.append(Token('kw', word, start_line, start_col))
                last_kind = 'kw'
            else:
                toks.append(Token('id', word, start_line, start_col))
                last_kind = 'id'
            continue
        # punctuation
        for p in PUNCT:
            if src.startswith(p, i):
                advance(len(p))
                toks.append(Token('punct', p, start_line, start_col))
                last_kind = 'punct'
                break
        else:
            advance(1)
            toks.append(Token('bad', ch, start_line, start_col))
            last_kind = 'bad'
    toks.append(Token('eof', None, line, col))
    return toks


def skip_escape(src, j, buf):
    """Handles the escapes that consume more than one character."""
    if j >= len(src):
        return j
    c = src[j]
    if c == 'u':
        if j + 1 < len(src) and src[j + 1] == '{':
            k = src.index('}', j)
            buf.append(chr(int(src[j + 2:k], 16)))
            return k + 1
        buf.append(chr(int(src[j + 1:j + 5], 16)))
        return j + 5
    if c == 'x':
        buf.append(chr(int(src[j + 1:j + 3], 16)))
        return j + 3
    return j + 1


def escape_char(nxt, src, j):
    if nxt == 'n':
        return '\n'
    if nxt == 't':
        return '\t'
    if nxt == 'r':
        return '\r'
    if nxt == 'b':
        return '\b'
    if nxt == 'f':
        return '\f'
    if nxt == 'v':
        return '\v'
    if nxt == '0':
        return '\0'
    if nxt == '\n':
        return ''
    if nxt == '':
        return ''
    if nxt == 'u' or nxt == 'x':
        return ''
    return nxt


def scan_template(src, i):
    """Returns (parts, end_index) where parts alternate between literal text
    and (source, token list) for the interpolations."""
    parts = []
    j = i + 1
    buf = []
    n = len(src)
    while True:
        if j >= n:
            raise JSyntaxError('unterminated template')
        c = src[j]
        if c == '\\':
            buf.append(escape_char(src[j + 1], src, j))
            j = skip_escape(src, j + 1, buf)
            continue
        if c == '`':
            j += 1
            break
        if c == '$' and j + 1 < n and src[j + 1] == '{':
            parts.append(''.join(buf))
            buf = []
            depth = 1
            k = j + 2
            while k < n and depth:
                if src[k] == '{':
                    depth += 1
                elif src[k] == '}':
                    depth -= 1
                elif src[k] in '"\'`':
                    q = src[k]
                    k += 1
                    while k < n and src[k] != q:
                        if src[k] == '\\':
                            k += 1
                        k += 1
                k += 1
            inner = src[j + 2:k - 1]
            parts.append(('expr', inner))
            j = k
            continue
        buf.append(c)
        j += 1
    if buf or not any(isinstance(p, tuple) for p in parts):
        parts.append(''.join(buf))
    return parts, j


def regex_allowed(last_kind):
    if last_kind is None:
        return False
    if last_kind in ('id', 'num', 'str', 'tmpl', 'regex', 'bad'):
        return True
    if last_kind == 'kw':
        # after a keyword a regexp is not allowed for the value keywords
        return False
    return False


class Parser:
    def __init__(self, toks, src=None):
        self.toks = toks
        self.pos = 0
        self.src = src or ''

    # ------------------------------------------------------------------
    @property
    def cur(self):
        return self.toks[self.pos]

    def peek(self, k=1):
        p = self.pos + k
        return self.toks[p] if p < len(self.toks) else self.toks[-1]

    def next(self):
        t = self.toks[self.pos]
        if t.kind != 'eof':
            self.pos += 1
        return t

    def at_punct(self, *vals):
        t = self.cur
        return t.kind == 'punct' and t.value in vals

    def at_kw(self, *vals):
        t = self.cur
        return t.kind == 'kw' and t.value in vals

    def expect_punct(self, val):
        t = self.cur
        if t.kind == 'punct' and t.value == val:
            self.pos += 1
            return t
        raise JSyntaxError("expected '%s' but found '%s'" %
                           (val, t.value), t.line, t.col)

    def expect_ident(self):
        t = self.cur
        if t.kind == 'id':
            self.pos += 1
            return t.value
        raise JSyntaxError('expected identifier, found %r' % (t.value,),
                           t.line, t.col)

    def eat_punct(self, val):
        if self.at_punct(val):
            self.pos += 1
            return True
        return False

    def eat_kw(self, val):
        if self.at_kw(val):
            self.pos += 1
            return True
        return False

    # ------------------------------------------------------------------
    def parse_program(self):
        stmts = []
        while self.cur.kind != 'eof':
            stmts.append(self.parse_statement())
        return ('block', stmts)

    def parse_statement(self):
        t = self.cur
        if t.kind == 'punct':
            if t.value == '{':
                self.pos += 1
                stmts = []
                while not self.at_punct('}') and self.cur.kind != 'eof':
                    stmts.append(self.parse_statement())
                self.expect_punct('}')
                return ('block', stmts)
            if t.value == ';':
                self.pos += 1
                return ('empty',)
        if t.kind == 'kw':
            w = t.value
            if w in ('var', 'let', 'const'):
                self.pos += 1
                return self.parse_var_decl(w)
            if w == 'function':
                self.pos += 1
                name = self.expect_ident()
                params, body = self.parse_function_rest()
                return ('funcdecl', name, params, body)
            if w == 'return':
                self.pos += 1
                if self.at_punct(';'):
                    self.pos += 1
                    return ('return', None)
                if self.at_punct('}'):
                    return ('return', None)
                if self.cur.line != t.line and self.cur.kind != 'eof':
                    if self.cur.kind == 'kw' and self.cur.value in (
                            'let', 'const', 'var', 'if', 'for', 'while'):
                        return ('return', None)
                expr = self.parse_expression()
                self.eat_punct(';')
                return ('return', expr)
            if w == 'if':
                self.pos += 1
                self.expect_punct('(')
                cond = self.parse_expression()
                self.expect_punct(')')
                then = self.parse_statement()
                els = None
                if self.eat_kw('else'):
                    els = self.parse_statement()
                return ('if', cond, then, els)
            if w == 'for':
                self.pos += 1
                self.expect_punct('(')
                init = None
                if self.at_punct(';'):
                    self.pos += 1
                    init = None
                elif self.at_kw('let') or self.at_kw('const') or \
                        self.at_kw('var'):
                    kind = self.cur.value
                    self.pos += 1
                    init = self.parse_var_decl(kind, no_semi=True)
                else:
                    init = ('expr', self.parse_expression_no_in())
                if self.at_kw('in') or self.at_kw('of'):
                    kw = self.cur.value
                    self.pos += 1
                    target = self.parse_assignment_expr()
                    self.expect_punct(')')
                    body = self.parse_statement()
                    return ('forof' if kw == 'of' else 'forin', init, target,
                            body)
                self.expect_punct(';')
                cond = None if self.at_punct(';') else self.parse_expression()
                self.expect_punct(';')
                step = None if self.at_punct(')') else self.parse_expression()
                self.expect_punct(')')
                body = self.parse_statement()
                return ('for', init, cond, step, body)
            if w == 'while':
                self.pos += 1
                self.expect_punct('(')
                cond = self.parse_expression()
                self.expect_punct(')')
                return ('while', cond, self.parse_statement())
            if w == 'do':
                self.pos += 1
                body = self.parse_statement()
                self.expect_kw('while')
                self.expect_punct('(')
                cond = self.parse_expression()
                self.expect_punct(')')
                self.eat_punct(';')
                return ('dowhile', cond, body)
            if w == 'break':
                self.pos += 1
                label = None
                if self.cur.kind == 'id':
                    label = self.next().value
                self.eat_punct(';')
                return ('break', label)
            if w == 'continue':
                self.pos += 1
                label = None
                if self.cur.kind == 'id':
                    label = self.next().value
                self.eat_punct(';')
                return ('continue', label)
            if w == 'throw':
                self.pos += 1
                expr = self.parse_expression()
                self.eat_punct(';')
                return ('throw', expr)
            if w == 'try':
                self.pos += 1
                body = self.parse_block()
                param, catch_body = None, None
                if self.eat_kw('catch'):
                    if self.eat_punct('('):
                        param = self.parse_binding()
                        self.expect_punct(')')
                    catch_body = self.parse_block()
                fin = None
                if self.eat_kw('finally'):
                    fin = self.parse_block()
                return ('try', body, param, catch_body, fin)
            if w == 'switch':
                self.pos += 1
                self.expect_punct('(')
                disc = self.parse_expression()
                self.expect_punct(')')
                self.expect_punct('{')
                cases = []
                while not self.at_punct('}'):
                    if self.eat_kw('case'):
                        test = self.parse_expression()
                        self.expect_punct(':')
                        stmts = []
                        while not (self.at_kw('case') or
                                   self.at_kw('default') or
                                   self.at_punct('}')):
                            stmts.append(self.parse_statement())
                        cases.append(('case', test, stmts))
                    elif self.eat_kw('default'):
                        self.expect_punct(':')
                        stmts = []
                        while not (self.at_kw('case') or
                                   self.at_kw('default') or
                                   self.at_punct('}')):
                            stmts.append(self.parse_statement())
                        cases.append(('default', None, stmts))
                    else:
                        self.pos += 1
                self.expect_punct('}')
                return ('switch', disc, cases)
            if w == 'class':
                return self.parse_class()
            if w == 'import':
                return self.parse_import()
            if w == 'export':
                return self.parse_export()
            if w == 'delete' or w == 'void' or w == 'typeof':
                expr = self.parse_expression()
                self.eat_punct(';')
                return ('expr', expr)
        # labelled statement
        if self.cur.kind == 'id' and self.peek().kind == 'punct' and \
                self.peek().value == ':':
            label = self.next().value
            self.pos += 1
            return ('label', label, self.parse_statement())
        expr = self.parse_expression()
        self.eat_punct(';')
        return ('expr', expr)

    def expect_kw(self, val):
        t = self.cur
        if t.kind == 'kw' and t.value == val:
            self.pos += 1
            return
        raise JSyntaxError("expected '%s'" % val, t.line, t.col)

    def parse_block(self):
        self.expect_punct('{')
        stmts = []
        while not self.at_punct('}') and self.cur.kind != 'eof':
            stmts.append(self.parse_statement())
        self.expect_punct('}')
        return ('block', stmts)

    # ------------------------------------------------------------------
    def parse_var_decl(self, kind, no_semi=False):
        decls = []
        while True:
            name = self.parse_binding()
            init = None
            if self.eat_punct('='):
                init = self.parse_assignment_expr()
            decls.append((kind, name, init))
            if not self.eat_punct(','):
                break
        if not no_semi:
            self.eat_punct(';')
        return ('var', decls)

    def parse_binding(self):
        if self.at_punct('{') or self.at_punct('['):
            return self.parse_destructure()
        return self.expect_ident()

    def parse_destructure(self):
        if self.at_punct('{'):
            self.pos += 1
            items = []
            while not self.at_punct('}'):
                key = None
                if self.cur.kind == 'id' or self.cur.kind == 'kw':
                    key = self.next().value
                    if self.eat_punct(':'):
                        sub = self.parse_binding()
                    else:
                        sub = key
                elif self.at_punct('['):
                    key = ('expr', self.parse_assignment_expr())
                    self.expect_punct(':')
                    sub = self.parse_binding()
                else:
                    sub = self.expect_ident()
                default = None
                if self.eat_punct('='):
                    default = self.parse_assignment_expr()
                rest = self.eat_punct('...')
                items.append((key, sub, default, rest))
                if not self.eat_punct(','):
                    break
            self.expect_punct('}')
            return ('objpat', items)
        self.pos += 1
        items = []
        while not self.at_punct(']'):
            if self.eat_punct('...'):
                sub = self.parse_binding()
                items.append((None, sub, None, True))
            else:
                sub = self.parse_binding()
                default = None
                if self.eat_punct('='):
                    default = self.parse_assignment_expr()
                items.append((None, sub, default, False))
            if not self.eat_punct(','):
                break
        self.expect_punct(']')
        return ('arrpat', items)

    # ------------------------------------------------------------------
    def parse_expression(self):
        expr = self.parse_assignment_expr()
        while self.at_punct(','):
            self.pos += 1
            nxt = self.parse_assignment_expr()
            expr = ('seq', expr, nxt)
        return expr

    def parse_expression_no_in(self):
        expr = self.parse_assignment_expr(no_in=True)
        while self.at_punct(','):
            self.pos += 1
            nxt = self.parse_assignment_expr(no_in=True)
            expr = ('seq', expr, nxt)
        return expr

    def parse_assignment_expr(self, no_in=False):
        left = self.parse_conditional(no_in)
        t = self.cur
        if t.kind == 'punct' and t.value in ASSIGN_OPS:
            self.pos += 1
            right = self.parse_assignment_expr(no_in)
            return ('assign', t.value, left, right)
        if t.kind == 'punct' and t.value == '=>':
            self.pos += 1
            return self.parse_arrow(left)
        return left

    def parse_arrow(self, left):
        params = []
        if left[0] == 'id':
            params = [left[1]]
        elif left[0] in ('objpat', 'arrpat'):
            params = [left]
        body = self.parse_arrow_body()
        return ('func', params, body, True)

    def parse_arrow_body(self):
        if self.at_punct('{'):
            self.pos += 1
            stmts = []
            while not self.at_punct('}') and self.cur.kind != 'eof':
                stmts.append(self.parse_statement())
            self.expect_punct('}')
            return ('block', stmts)
        expr = self.parse_assignment_expr()
        return ('return', expr)

    def parse_conditional(self, no_in=False):
        cond = self.parse_binary(no_in)
        if self.at_punct('?'):
            self.pos += 1
            then = self.parse_assignment_expr()
            self.expect_punct(':')
            els = self.parse_assignment_expr(no_in)
            return ('cond', cond, then, els)
        return cond

    def parse_binary(self, no_in=False):
        left = self.parse_unary()
        while True:
            t = self.cur
            if t.kind == 'punct':
                op = t.value
                if op in ('||', '&&', '??', '|', '^', '&', '==', '!=', '===',
                          '!==', '<', '>', '<=', '>=', '+', '-', '*', '/',
                          '%', '**', '<<', '>>', '>>>'):
                    if no_in and op == 'in':
                        break
                    self.pos += 1
                    right = self.parse_unary()
                    left = ('binop', op, left, right)
                    continue
                if op == 'instanceof':
                    self.pos += 1
                    right = self.parse_unary()
                    left = ('binop', 'instanceof', left, right)
                    continue
                if op == 'in' and not no_in:
                    self.pos += 1
                    right = self.parse_unary()
                    left = ('binop', 'in', left, right)
                    continue
            break
        return left

    def parse_unary(self):
        t = self.cur
        if t.kind == 'punct' and t.value in ('-', '+', '!', '~'):
            self.pos += 1
            operand = self.parse_unary()
            if t.value == '-' and operand[0] == 'num' and \
                    isinstance(operand[1], (int, float)):
                operand = ('num', -operand[1])
            return ('unary', t.value, operand)
        if t.kind == 'punct' and t.value == '++':
            self.pos += 1
            return ('unary', '++', self.parse_unary())
        if t.kind == 'punct' and t.value == '--':
            self.pos += 1
            return ('unary', '--', self.parse_unary())
        if t.kind == 'kw' and t.value in ('typeof', 'void', 'delete'):
            self.pos += 1
            return ('unary', t.value, self.parse_unary())
        if t.kind == 'kw' and t.value == 'new':
            self.pos += 1
            callee = self.parse_primary()
            args = []
            if self.eat_punct('('):
                while not self.at_punct(')'):
                    args.append(self.parse_arg())
                    if not self.eat_punct(','):
                        break
                self.expect_punct(')')
            node = ('new', callee, args)
            return self.parse_postfix_chain(node)
        if t.kind == 'kw' and t.value == 'await':
            self.pos += 1
            return ('unary', 'await', self.parse_unary())
        return self.parse_postfix()

    def parse_postfix(self):
        node = self.parse_primary()
        return self.parse_postfix_chain(node)

    def parse_postfix_chain(self, node):
        while True:
            t = self.cur
            if t.kind == 'punct' and t.value == '.':
                self.pos += 1
                nxt = self.cur
                if nxt.kind in ('id', 'kw'):
                    self.pos += 1
                    node = ('member', node, nxt.value, False)
                else:
                    raise JSyntaxError('bad member access', nxt.line, nxt.col)
                continue
            if t.kind == 'punct' and t.value == '?.':
                self.pos += 1
                if self.at_punct('('):
                    self.pos += 1
                    args = []
                    while not self.at_punct(')'):
                        args.append(self.parse_arg())
                        if not self.eat_punct(','):
                            break
                    self.expect_punct(')')
                    node = ('optcall', node, args)
                    continue
                if self.at_punct('['):
                    self.pos += 1
                    idx = self.parse_expression()
                    self.expect_punct(']')
                    node = ('optindex', node, idx)
                    continue
                nxt = self.cur
                if nxt.kind in ('id', 'kw'):
                    self.pos += 1
                    node = ('member', node, nxt.value, True)
                continue
            if t.kind == 'punct' and t.value == '[':
                self.pos += 1
                idx = self.parse_expression()
                self.expect_punct(']')
                node = ('index', node, idx)
                continue
            if t.kind == 'punct' and t.value == '(':
                self.pos += 1
                args = []
                while not self.at_punct(')'):
                    args.append(self.parse_arg())
                    if not self.eat_punct(','):
                        break
                self.expect_punct(')')
                node = ('call', node, args)
                continue
            if t.kind == 'punct' and t.value in ('++', '--'):
                self.pos += 1
                node = ('postfix', t.value, node)
                continue
            if t.kind == 'punct' and t.value == '`':
                tmpl = self.cur.value
                self.pos += 1
                node = ('tagtmpl', node, tmpl)
                continue
            break
        return node

    def parse_arg(self):
        if self.at_punct('...'):
            self.pos += 1
            return ('spread', self.parse_assignment_expr())
        return self.parse_assignment_expr()

    # ------------------------------------------------------------------
    def parse_primary(self):
        t = self.cur
        if t.kind == 'num':
            self.pos += 1
            return ('num', t.value)
        if t.kind == 'str':
            self.pos += 1
            return ('str', t.value)
        if t.kind == 'tmpl':
            self.pos += 1
            return ('tmpl', t.value)
        if t.kind == 'regex':
            self.pos += 1
            return ('regex', t.value[0], t.value[1])
        if t.kind == 'id':
            self.pos += 1
            return ('id', t.value)
        if t.kind == 'kw':
            if t.value in ('null', 'true', 'false'):
                self.pos += 1
                return ('const', {'null': None, 'true': True,
                                  'false': False}[t.value])
            if t.value == 'this':
                self.pos += 1
                return ('this',)
            if t.value == 'function':
                self.pos += 1
                name = None
                if self.cur.kind == 'id':
                    name = self.next().value
                params, body = self.parse_function_rest()
                return ('func', params, body, False, name)
            if t.value == 'new':
                self.pos += 1
                callee = self.parse_primary()
                args = []
                if self.eat_punct('('):
                    while not self.at_punct(')'):
                        args.append(self.parse_arg())
                        if not self.eat_punct(','):
                            break
                    self.expect_punct(')')
                return self.parse_postfix_chain(('new', callee, args))
            if t.value == 'super':
                self.pos += 1
                return ('super',)
            if t.value in ('let', 'const', 'var', 'get', 'set', 'of', 'as',
                           'from', 'async', 'static'):
                self.pos += 1
                return ('id', t.value)
        if t.kind == 'punct':
            if t.value == '(':
                self.pos += 1
                # possibly an arrow function
                if self.at_punct(')'):
                    self.pos += 1
                    self.expect_punct('=>')
                    return ('func', [], self.parse_arrow_body(), True)
                inner = self.parse_expression()
                self.expect_punct(')')
                if self.at_punct('=>'):
                    self.pos += 1
                    return self.parse_arrow(('expr', inner))
                return inner
            if t.value == '[':
                return self.parse_array()
            if t.value == '{':
                return self.parse_object()
            if t.value == '!':
                return self.parse_unary()
            if t.value == '-':
                return self.parse_unary()
            if t.value == '+':
                return self.parse_unary()
            if t.value == '~':
                return self.parse_unary()
            if t.value == '...':
                self.pos += 1
                return ('spread', self.parse_assignment_expr())
        raise JSyntaxError('unexpected token %r' % (t.value,), t.line, t.col)

    def parse_array(self):
        self.expect_punct('[')
        elems = []
        while not self.at_punct(']'):
            if self.at_punct(','):
                self.pos += 1
                elems.append(('hole',))
                continue
            if self.at_punct('...'):
                self.pos += 1
                elems.append(('spread', self.parse_assignment_expr()))
            else:
                elems.append(self.parse_assignment_expr())
            if not self.eat_punct(','):
                break
        self.expect_punct(']')
        return ('array', elems)

    def parse_object(self):
        self.expect_punct('{')
        props = []
        while not self.at_punct('}'):
            if self.at_punct('...'):
                self.pos += 1
                props.append(('spread', self.parse_assignment_expr(), None,
                              False, False))
                if not self.eat_punct(','):
                    break
                continue
            key = None
            computed = False
            if self.at_punct('['):
                self.pos += 1
                key = ('expr', self.parse_assignment_expr())
                self.expect_punct(']')
                computed = True
            elif self.cur.kind == 'str':
                key = ('str', self.next().value)
            elif self.cur.kind == 'num':
                key = ('num', self.next().value)
            elif self.cur.kind in ('id', 'kw'):
                key = ('id', self.next().value)
            else:
                raise JSyntaxError('bad object key', self.cur.line,
                                   self.cur.col)
            if self.at_punct('('):
                # method definition
                params, body = self.parse_function_rest()
                props.append(('method', key, params, body, False, computed))
                if not self.eat_punct(','):
                    break
                continue
            if self.at_punct(':'):
                self.pos += 1
                props.append(('value', key, self.parse_assignment_expr(),
                              False, computed))
            elif self.cur.kind == 'punct' and self.cur.value in (',', '}') or \
                    self.cur.kind == 'eof':
                if key[0] == 'id':
                    props.append(('value', key, ('id', key[1]), False,
                                  computed))
                else:
                    raise JSyntaxError('bad shorthand property')
            else:
                raise JSyntaxError('bad property', self.cur.line, self.cur.col)
            if not self.eat_punct(','):
                break
        self.expect_punct('}')
        return ('object', props)

    def parse_function_rest(self):
        self.expect_punct('(')
        params = []
        while not self.at_punct(')'):
            if self.eat_punct('...'):
                params.append(('rest', self.parse_binding()))
            else:
                params.append(('param', self.parse_binding()))
            if self.eat_punct('='):
                params[-1] = ('param', params[-1][1],
                              self.parse_assignment_expr())
            if not self.eat_punct(','):
                break
        self.expect_punct(')')
        body = self.parse_function_body()
        return params, body

    def parse_function_body(self):
        self.expect_punct('{')
        stmts = []
        while not self.at_punct('}') and self.cur.kind != 'eof':
            stmts.append(self.parse_statement())
        self.expect_punct('}')
        return ('block', stmts)

    def parse_class(self):
        self.expect_kw('class')
        name = None
        if self.cur.kind == 'id':
            name = self.next().value
        parent = None
        if self.eat_kw('extends'):
            parent = self.parse_postfix()
        self.expect_punct('{')
        members = []
        while not self.at_punct('}'):
            if self.eat_punct(';'):
                continue
            is_static = False
            if self.at_kw('static'):
                self.pos += 1
                is_static = True
            kind = 'method'
            if self.at_kw('get') and not self.at_punct('('):
                kind = 'getter'
                self.pos += 1
            elif self.at_kw('set') and not self.at_punct('('):
                kind = 'setter'
                self.pos += 1
            if self.at_punct('['):
                self.pos += 1
                key = ('expr', self.parse_assignment_expr())
                self.expect_punct(']')
                computed = True
            else:
                key = ('id' if self.cur.kind == 'id' else 'str',
                       self.next().value)
                computed = False
            if self.at_punct('('):
                params, body = self.parse_function_rest()
                members.append((kind, key, params, body, is_static, computed))
                continue
            if self.eat_punct('='):
                members.append(('field', key, self.parse_assignment_expr(),
                                is_static, computed))
                self.eat_punct(';')
                continue
            members.append(('field', key, None, is_static, computed))
        self.expect_punct('}')
        return ('class', name, parent, members)

    def parse_import(self):
        self.expect_kw('import')
        names = []
        default = None
        if self.cur.kind == 'id':
            default = self.next().value
            if self.eat_punct(','):
                pass
            else:
                if self.eat_kw('from'):
                    src = self.next().value
                    self.eat_punct(';')
                    return ('import', default, names, src)
        if self.eat_punct('{'):
            while not self.at_punct('}'):
                name = self.expect_ident()
                alias = name
                if self.eat_kw('as'):
                    alias = self.expect_ident()
                names.append((name, alias))
                if not self.eat_punct(','):
                    break
            self.expect_punct('}')
        if self.eat_punct('*'):
            self.expect_kw('as')
            alias = self.expect_ident()
            names.append(('*', alias))
        if self.eat_kw('from'):
            src = self.next().value
        self.eat_punct(';')
        return ('import', default, names, src)

    def parse_export(self):
        self.expect_kw('export')
        if self.at_kw('default'):
            self.pos += 1
            expr = self.parse_assignment_expr()
            self.eat_punct(';')
            return ('exportdefault', expr)
        if self.at_punct('{'):
            self.pos += 1
            names = []
            while not self.at_punct('}'):
                name = self.expect_ident()
                alias = name
                if self.eat_kw('as'):
                    alias = self.expect_ident()
                names.append((name, alias))
                if not self.eat_punct(','):
                    break
            self.expect_punct('}')
            self.eat_kw('from')
            if self.cur.kind in ('str', 'id'):
                src = self.next().value
            self.eat_punct(';')
            return ('exportnames', names, src if 'src' in dir() else None)
        if self.at_kw('var') or self.at_kw('let') or self.at_kw('const'):
            kind = self.cur.value
            self.pos += 1
            decl = self.parse_var_decl(kind)
            return ('exportdecl', kind, decl)
        if self.at_kw('function'):
            self.pos += 1
            name = self.expect_ident()
            params, body = self.parse_function_rest()
            return ('exportdecl', 'function', ('funcdecl', name, params, body))
        if self.at_kw('class'):
            node = self.parse_class()
            return ('exportdecl', 'class', node)
        expr = self.parse_expression()
        self.eat_punct(';')
        return ('exportexpr', expr)
