                return
            obj = obj.proto
        self.props[name] = value

    def own(self, name):
        return name in self.props

    def keys(self):
        return [k for k in self.props]

    def repr(self):
        return '[object Object]'


class JSArray:
    def __init__(self, items=None, proto=None):
        self.items = list(items or [])
        self.proto = proto if proto is not None else None

    def get(self, name):
        if isinstance(name, str) and name.isdigit():
            i = int(name)
            return self.items[i] if i < len(self.items) else UNDEF
        if name == 'length':
            return len(self.items)
        obj = self.proto
        while obj is not None:
            if name in obj.props:
                return obj.props[name]
            obj = obj.proto
        return UNDEF

    def has(self, name):
