                self.items.append(UNDEF)
            self.items[i] = value
            return
        self.props = getattr(self, 'props', None) or {}
        self.props[name] = value

    def own(self, name):
        if isinstance(name, str) and name.isdigit():
            return int(name) < len(self.items)
        if name == 'length':
            return True
        return name in getattr(self, 'props', {})

    def keys(self):
        out = [str(i) for i in range(len(self.items))]
        out.extend(getattr(self, 'props', {}).keys())
        return out

    def repr(self):
        return '[object Array]'


class JSMap:
    def __init__(self):
        self.entries = []
        self.proto = None

    def find(self, key):
        for i, (k, _) in enumerate(self.entries):
            if same_value_zero(k, key):
                return i
        return None


class JSSet:
    def __init__(self):
        self.items = []
        self.proto = None

    def has(self, value):
        return any(same_value_zero(v, value) for v in self.items)


class JSCallable:
    name = ''

    def __init__(self, name=''):
        self.name = name
        self.proto = None
        self.props = {}

    def get(self, name):
        if name in self.props:
            return self.props[name]
        obj = self.proto
        while obj is not None:
            if name in obj.props:
                return obj.props[name]
            obj = obj.proto
        return UNDEF

    def has(self, name):
        return name in self.props

    def set(self, name, value):
        self.props[name] = value

    def own(self, name):
        return name in self.props

    def keys(self):
        return list(self.props.keys())

    def repr(self):
        return 'function %s() { [native code] }' % self.name


class JSNativeFunc(JSCallable):
    def __init__(self, name, fn, length=0, ctor=False):
        super().__init__(name)
        self.fn = fn
        self.length = length
        self.is_ctor = ctor

    def call(self, ctx, this, args):
        return self.fn(ctx, this, args)


class JSUserFunc(JSCallable):
    def __init__(self, name, params, body, env, is_arrow=False,
                 this_val=UNDEF):
        super().__init__(name or '')
        self.params = params
        self.body = body
        self.env = env
        self.is_arrow = is_arrow
        self.this_val = this_val
        self.is_ctor = True

    def call(self, ctx, this, args):
        from .builtins import call_user_function
        return call_user_function(self, ctx, this, args)


class JSProxy:
    def __init__(self, target, handler):
        self.target = target
        self.handler = handler
        self.proto = None

    def get(self, name):
        trap = self.handler.get('get')
        if trap is not None:
            return trap(self.handler, self.target, name, self)
        return get_property(self.target, name)

    def has(self, name):
        trap = self.handler.get('has')
        if trap is not None:
            return to_boolean(trap(self.handler, self.target, name))
        return has_property(self.target, name)

    def set(self, name, value):
        trap = self.handler.get('set')
        if trap is not None:
            return trap(self.handler, self.target, name, value, self)
        set_property(self.target, name, value)
        return True

    def own(self, name):
        return has_property(self.target, name)

    def keys(self):
        return own_keys(self.target)

    def repr(self):
        return '[object Object]'


class JSError(Exception):
    def __init__(self, kind, message, stack=None):
        self.kind = kind
        self.message = message
        self.stack = stack or []
        self.js_value = JSObject({'name': kind, 'message': message})


class JSRegExp:
    def __init__(self, source, flags):
        self.source = source
        self.flags = flags
        self.global_flag = 'g' in flags
        self.ignore_case = 'i' in flags
        self.multiline = 'm' in flags
        self.dot_all = 's' in flags
        self.unicode = 'u' in flags
        self.sticky = 'y' in flags
        self.last_index = 0
        self.proto = None
        self.props = {}

    def get(self, name):
        if name == 'lastIndex':
            return self.last_index
        if name == 'source':
            return self.source
        if name == 'flags':
            return self.flags
        if name == 'global':
            return self.global_flag
        if name == 'ignoreCase':
            return self.ignore_case
        if name == 'multiline':
            return self.multiline
        if name == 'dotAll':
            return self.dot_all
        if name == 'unicode':
            return self.unicode
        if name == 'sticky':
            return self.sticky
        obj = self.proto
        while obj is not None:
            if name in obj.props:
                return obj.props[name]
            obj = obj.proto
        return UNDEF

    def has(self, name):
        return True

    def set(self, name, value):
        if name == 'lastIndex':
            self.last_index = to_number(value)
        else:
            self.props[name] = value

    def own(self, name):
        return True

    def keys(self):
        return []

    def repr(self):
        return '/%s/%s' % (self.source, self.flags)


class JSSymbol:
    def __init__(self, description):
        self.description = description

    def repr(self):
        return 'Symbol(%s)' % (self.description or '')


class JSErrorObj(JSCallable):
    """Error constructors (Error, TypeError, ...)."""


class Context:
    """Holds the globals and reports errors."""

    def __init__(self):
        self.globals = None
        self.stdout = ''
        self.stderr = ''
        self.exception = None


# ----------------------------------------------------------------------
# conversions
# ----------------------------------------------------------------------

def to_boolean(v):
    if v is None or v is UNDEF:
        return False
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return v != 0 and v == v
    if isinstance(v, str):
        return v != ''
    return True


def to_number(v):
    if isinstance(v, bool):
        return 1 if v else 0
    if isinstance(v, (int, float)):
        return v
    if v is None:
        return 0
    if v is UNDEF:
        return float('nan')
    if isinstance(v, str):
        s = v.strip()
        if s == '':
            return 0
        try:
            if s.lower().startswith('0x') or s.lower().startswith('-0x'):
                return int(s, 16) if not s.lower().startswith('-') \
                    else -int(s[3:], 16)
            if s.lower().startswith('0b'):
                return int(s[2:], 2)
            if s.lower().startswith('0o'):
                return int(s[2:], 8)
            if s.lower().startswith('inf') or s.lower() == '+inf':
                return float('inf')
            if s.lower().startswith('-inf'):
                return float('-inf')
            return int(s) if s.isdigit() else float(s)
        except ValueError:
            try:
                return float(s)
            except ValueError:
                return float('nan')
    if isinstance(v, JSArray):
        if len(v.items) == 0:
            return 0
        if len(v.items) == 1:
            return to_number(v.items[0])
        return float('nan')
    return float('nan')


def to_string(v):
    if isinstance(v, str):
        return v
    if v is UNDEF:
        return 'undefined'
    if v is NULL:
        return 'null'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, float):
        if v != v:
            return 'NaN'
        if v == float('inf'):
            return 'Infinity'
        if v == float('-inf'):
            return '-Infinity'
        if v == int(v) and abs(v) < 1e21:
            return str(int(v))
        return repr(v)
    if isinstance(v, int):
        return str(v)
    if isinstance(v, JSArray):
        return ', '.join('' if (x is UNDEF or x is NULL) else to_string(x)
                         for x in v.items)
    if isinstance(v, JSObject):
        return v.repr()
    if isinstance(v, JSCallable):
        return v.repr()
    if isinstance(v, JSRegExp):
        return v.repr()
    if isinstance(v, JSSymbol):
        return v.repr()
    return str(v)


def same_value(a, b):
    if a is UNDEF or b is UNDEF:
        return a is UNDEF and b is UNDEF
    if a is NULL or b is NULL:
        return a is NULL and b is NULL
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    return a is b


def same_value_zero(a, b):
    return same_value(a, b)


def typeof(v):
    if v is UNDEF:
        return 'undefined'
    if v is NULL:
        return 'object'
    if isinstance(v, bool):
        return 'boolean'
    if isinstance(v, (int, float)):
        return 'number'
    if isinstance(v, str):
        return 'string'
    if isinstance(v, JSSymbol):
        return 'symbol'
    if isinstance(v, JSNativeFunc) or isinstance(v, JSUserFunc) or \
            isinstance(v, JSCallable):
        return 'function'
    return 'object'


def is_callable(v):
    return isinstance(v, (JSNativeFunc, JSUserFunc))


def to_primitive(v, hint='default'):
    if isinstance(v, (JSObject, JSArray)):
        if hint == 'string':
            fn = get_property(v, 'toString')
        else:
            fn = get_property(v, 'valueOf')
        if fn is not UNDEF and is_callable(fn):
            try:
                res = call_function(fn, v, [])
                if not isinstance(res, (JSObject, JSArray)):
                    return res
            except Exception:
                pass
        if hint == 'string':
            fn2 = get_property(v, 'valueOf')
        else:
            fn2 = get_property(v, 'toString')
        if fn2 is not UNDEF and is_callable(fn2):
            try:
                res = call_function(fn2, v, [])
                if not isinstance(res, (JSObject, JSArray)):
                    return res
            except Exception:
                pass
        raise JSError('TypeError', 'Cannot convert object to primitive value')
    return v


def equals(a, b):
    if a is UNDEF or b is UNDEF:
        return True
    if a is NULL or b is NULL:
        return True
    if isinstance(a, bool) and isinstance(b, (int, float)):
        return to_number(a) == b
    if isinstance(b, bool) and isinstance(a, (int, float)):
        return a == to_number(b)
    if isinstance(a, bool) and isinstance(b, str):
        return to_number(a) == to_number(b)
    if isinstance(b, bool) and isinstance(a, str):
        return to_number(a) == to_number(b)
    if isinstance(a, (int, float)) and isinstance(b, str):
        return a == to_number(b)
    if isinstance(b, (int, float)) and isinstance(a, str):
        return to_number(a) == b
    if isinstance(a, (int, float, bool)) and isinstance(b, JSArray):
        return equals(a, to_primitive(b, 'number'))
    if isinstance(b, (int, float, bool)) and isinstance(a, JSArray):
        return equals(to_primitive(a, 'number'), b)
    if isinstance(a, str) and isinstance(b, JSArray):
        return a == to_string(to_primitive(b, 'string'))
    if isinstance(b, str) and isinstance(a, JSArray):
        return to_string(to_primitive(a, 'string')) == b
    if isinstance(a, (JSObject, JSArray)) and isinstance(b, (JSObject, JSArray)):
        return a is b
    if a is NULL or b is NULL:
        return False
    if a is UNDEF or b is UNDEF:
        return False
    return False


def strict_equals(a, b):
    if typeof(a) != typeof(b):
        if isinstance(a, bool) and isinstance(b, (int, float)):
            return to_number(a) == b
        if isinstance(b, bool) and isinstance(a, (int, float)):
            return a == to_number(b)
        return False
    if a is UNDEF or b is UNDEF:
        return True
    if a is NULL or b is NULL:
        return True
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    return a is b


