class Env:
    __slots__ = ('vars', 'parent', 'this', 'kind', 'func')

    def __init__(self, parent=None, this=UNDEF, kind='block', func=None):
        self.vars = {}
        self.parent = parent
        self.this = this
        self.kind = kind
        self.func = func

    def lookup(self, name):
        e = self
        while e is not None:
            if name in e.vars:
                return e
            e = e.parent
        return None

    def get(self, name):
        e = self.lookup(name)
        if e is None:
            raise ReferenceError(name)
        return e.vars[name]

    def set(self, name, value):
        e = self.lookup(name)
        if e is None:
