def eval_binop(node, env, ctx):
    op = node[1]
    if op == '&&':
        left = evaluate(node[2], env, ctx)
        return evaluate(node[3], env, ctx) if to_boolean(left) else left
    if op == '||':
        left = evaluate(node[2], env, ctx)
        return left if to_boolean(left) else evaluate(node[3], env, ctx)
    if op == '??':
        left = evaluate(node[2], env, ctx)
        if left is UNDEF or left is NULL:
            return evaluate(node[3], env, ctx)
        return left
    left = evaluate(node[2], env, ctx)
    right = evaluate(node[3], env, ctx)
    return apply_binop(op, left, right)


def apply_binop(op, left, right):
    if op == '+':
        lp = to_primitive(left)
        rp = to_primitive(right)
        if isinstance(lp, str) or isinstance(rp, str):
            return to_string(lp) + to_string(rp)
        return to_number(lp) + to_number(rp)
    if op == '-':
        return to_number(left) - to_number(right)
    if op == '*':
        return to_number(left) * to_number(right)
    if op == '/':
        ln, rn = to_number(left), to_number(right)
        if rn == 0:
            if ln == 0 or ln != ln:
                return float('nan')
            return float('inf') if (ln > 0) == (rn == 0 and rn == 0) else \
                float('nan')
        return ln / rn
    if op == '%':
        ln, rn = to_number(left), to_number(right)
        if rn == 0 or ln != ln or rn != rn:
            return float('nan')
        return ln - rn * int(ln / rn) if ln >= 0 else ln - rn * -int(-ln / rn)
    if op == '**':
        return to_number(left) ** to_number(right)
    if op in ('==', '!='):
        res = equals(left, right)
        return res if op == '==' else not res
    if op in ('===', '!=='):
        res = strict_equals(left, right)
        return res if op == '===' else not res
    if op == '<':
        return compare_lt(left, right, False)
    if op == '>':
        return compare_lt(right, left, False)
    if op == '<=':
        return not compare_lt(right, left, True)
    if op == '>=':
        return not compare_lt(left, right, True)
    if op == 'instanceof':
        return js_instanceof(left, right)
    if op == 'in':
        return has_property(right, to_string(left))
    if op == '&':
        return to_int32(left) & to_int32(right)
    if op == '|':
        return to_int32(left) | to_int32(right)
    if op == '^':
        return to_int32(left) ^ to_int32(right)
    if op == '<<':
        return to_int32(left) << (to_uint32(right) & 31)
    if op == '>>':
        return to_int32(left) >> (to_uint32(right) & 31)
    if op == '>>>':
        return to_uint32(left) >> (to_uint32(right) & 31)
    raise JSThrow(make_error_object('SyntaxError', 'unsupported operator'))


def compare_lt(a, b, equal_or_nan):
    ap = to_primitive(a, 'number')
    bp = to_primitive(b, 'number')
    if isinstance(ap, str) and isinstance(bp, str):
        return ap < bp
    an, bn = to_number(ap), to_number(bp)
    if an != an or bn != bn:
        return False
    return an < bn


def js_instanceof(left, right):
    if isinstance(right, JSUserFunc):
        proto = get_property(right, 'prototype')
    else:
        proto = get_property(right, 'prototype')
    obj = left
    while isinstance(obj, (JSObject, JSArray)):
        if obj.proto is proto:
            return True
        obj = obj.proto
    return False


def to_int32(v):
    n = to_number(v)
    if n != n:
        return 0
    if n in (float('inf'), float('-inf')):
        return 0
    n = int(n)
    n &= 0xFFFFFFFF
    if n >= 0x80000000:
        n -= 0x100000000
    return n


def to_uint32(v):
    n = to_number(v)
    if n != n:
        return 0
    if n in (float('inf'), float('-inf')):
        return 0
    return int(n) & 0xFFFFFFFF


def eval_unary(node, env, ctx):
    op = node[1]
    if op == 'typeof':
        operand = node[2]
        if operand[0] == 'id':
            e = env.lookup(operand[1])
            if e is None and operand[1] not in ctx.globals.vars:
                return 'undefined'
        return typeof(evaluate(operand, env, ctx))
    if op == 'void':
        evaluate(node[2], env, ctx)
        return UNDEF
    if op == 'delete':
        target = node[2]
        if target[0] == 'member':
            obj = evaluate(target[1], env, ctx)
            try:
                del obj.props[target[2]]
            except Exception:
                pass
            return True
        if target[0] == 'index':
            obj = evaluate(target[1], env, ctx)
            key = index_key(evaluate(target[2], env, ctx))
            try:
                del obj.props[key]
            except Exception:
                pass
            return True
        return True
    val = evaluate(node[2], env, ctx)
    if op == '!':
        return not to_boolean(val)
    if op == '-':
        return -to_number(val)
    if op == '+':
        return to_number(val)
    if op == '~':
        return ~to_int32(val)
    if op == '++':
        ref = eval_ref(node[2], env, ctx)
        new = to_number(get_ref(ref)) + 1
        set_ref(ref, new)
        return new
    if op == '--':
        ref = eval_ref(node[2], env, ctx)
        new = to_number(get_ref(ref)) - 1
        set_ref(ref, new)
        return new
    if op == 'await':
        return val
    raise JSThrow(make_error_object('SyntaxError', 'unsupported operator'))


def eval_postfix(node, env, ctx):
    op = node[1]
    ref = eval_ref(node[2], env, ctx)
    old = get_ref(ref)
    new = to_number(old) + (1 if op == '++' else -1)
    set_ref(ref, new)
    return old


def eval_ref(node, env, ctx):
    if node[0] == 'id':
        return ('env', node[1], env)
    if node[0] == 'member':
        obj = evaluate(node[1], env, ctx)
        return ('prop', obj, node[2])
    if node[0] == 'index':
        obj = evaluate(node[1], env, ctx)
        key = index_key(evaluate(node[2], env, ctx))
        return ('prop', obj, key)
    raise JSThrow(make_error_object('SyntaxError', 'invalid left-hand side'))


def get_ref(ref):
    if ref[0] == 'env':
        return ref[2].get(ref[1]) if ref[2].lookup(ref[1]) is not None \
            else ctx_global_get(ref[1])
    return get_property(ref[1], ref[2])


def ctx_global_get(name):
    raise JSThrow(make_error_object('ReferenceError',
                                    '%s is not defined' % name))


def set_ref(ref, value):
    if ref[0] == 'env':
        if ref[2].lookup(ref[1]) is not None:
            ref[2].set(ref[1], value)
        return
    set_property(ref[1], ref[2], value)


def eval_assign(node, env, ctx):
    op = node[1]
    target = node[2]
    value_node = node[3]
    if op == '=':
        if target[0] in ('objpat', 'arrpat'):
            value = evaluate(value_node, env, ctx)
            assign_destructure(target, value, env, ctx)
            return value
        ref = eval_ref(target, env, ctx)
        value = evaluate(value_node, env, ctx)
        set_ref(ref, value)
        return value
    ref = eval_ref(target, env, ctx)
    old = get_ref(ref)
    value = evaluate(value_node, env, ctx)
    if op == '&&=':
        if not to_boolean(old):
            return old
        new = value
    elif op == '||=':
        if to_boolean(old):
            return old
        new = value
    elif op == '??=':
        if old is not UNDEF and old is not NULL:
            return old
        new = value
    else:
        new = apply_binop(op[:-1], old, value)
    set_ref(ref, new)
    return new


def assign_destructure(pattern, value, env, ctx):
    if pattern[0] == 'arrpat':
        items = to_list(value)
        for i, (_, name, default, _) in enumerate(pattern[1]):
            v = items[i] if i < len(items) else UNDEF
            if v is UNDEF and default is not None:
                v = evaluate(default, env, ctx)
            assign_target(name, v, env, ctx)
        return
    for key, name, default, _ in pattern[1]:
        if key is None:
            v = get_property(value, name)
        elif key[0] == 'expr':
            v = get_property(value, to_string(evaluate(key[1], env, ctx)))
        else:
            v = get_property(value, key[1])
        if v is UNDEF and default is not None:
            v = evaluate(default, env, ctx)
        assign_target(name, v, env, ctx)


def assign_target(name, value, env, ctx):
    if isinstance(name, str):
        e = env.lookup(name)
        if e is not None:
            e.vars[name] = value
        else:
            ctx.globals.vars[name] = value
    else:
        evaluate(('assign', '=', name, ('const', value)), env, ctx)


# ----------------------------------------------------------------------
# statements
# ----------------------------------------------------------------------

def exec_stmt(node, env, ctx):
    kind = node[0]
    if kind == 'block':
        block_env = Env(env, env.this, 'block')
        for st in node[1]:
            exec_stmt(st, block_env, ctx)
        return
    if kind == 'empty':
        return
    if kind == 'var':
        for kind2, name, init in node[1]:
            if isinstance(name, str):
                value = UNDEF
                if init is not None:
                    value = evaluate(init, env, ctx)
                env.declare(name, value)
            else:
                value = evaluate(init, env, ctx) if init is not None else UNDEF
                assign_destructure(name, value, env, ctx)
        return
    if kind == 'funcdecl':
        fn = JSUserFunc(node[1], node[2], node[3], env, False)
        env.declare(node[1], fn)
        return
    if kind == 'expr':
        evaluate(node[1], env, ctx)
        return
    if kind == 'if':
        if to_boolean(evaluate(node[1], env, ctx)):
            exec_stmt(node[2], env, ctx)
        elif node[3] is not None:
            exec_stmt(node[3], env, ctx)
        return
    if kind == 'for':
        loop_env = Env(env, env.this, 'block')
        if node[1] is not None:
            exec_stmt(node[1], loop_env, ctx)
        while True:
            if node[2] is not None and not to_boolean(
                    evaluate(node[2], loop_env, ctx)):
                break
            try:
                exec_stmt(node[4], loop_env, ctx)
            except JSBreak:
                break
            except JSContinue:
                pass
            if node[3] is not None:
                evaluate(node[3], loop_env, ctx)
        return
    if kind == 'forin' or kind == 'forof':
        loop_env = Env(env, env.this, 'block')
        target = evaluate(node[2], env, ctx)
        if kind == 'forin':
            keys = own_keys(target)
            if isinstance(target, JSArray):
                keys = [k for k in keys]
        else:
            keys = to_list(target)
        for key in keys:
            decl = node[1]
            if decl is None:
                continue
            if decl[0] == 'var':
                for _, name, _ in decl[1]:
                    assign_target(name, key, loop_env, ctx)
            elif decl[0] == 'expr':
                assign_target_from_expr(decl[1], key, loop_env, ctx)
            else:
                assign_target_from_expr(decl, key, loop_env, ctx)
            try:
                exec_stmt(node[3], loop_env, ctx)
            except JSBreak:
                break
            except JSContinue:
                continue
        return
    if kind == 'while':
        while to_boolean(evaluate(node[1], env, ctx)):
            try:
                exec_stmt(node[2], env, ctx)
            except JSBreak:
                break
            except JSContinue:
                continue
        return
    if kind == 'dowhile':
        while True:
            try:
                exec_stmt(node[2], env, ctx)
            except JSBreak:
                break
            except JSContinue:
                pass
            if not to_boolean(evaluate(node[1], env, ctx)):
                break
        return
    if kind == 'return':
        value = evaluate(node[1], env, ctx) if node[1] is not None else UNDEF
        raise JSReturn(value)
    if kind == 'break':
        raise JSBreak(node[1])
    if kind == 'continue':
        raise JSContinue(node[1])
    if kind == 'throw':
        raise JSThrow(evaluate(node[1], env, ctx))
    if kind == 'try':
        try:
            try:
                exec_stmt(node[1], Env(env, env.this, 'block'), ctx)
            except JSThrow as t:
                if node[3] is None:
                    raise
                cenv = Env(env, env.this, 'block')
                if node[2] is not None:
                    cenv.declare(node[2], t.value)
                exec_stmt(node[3], cenv, ctx)
        finally:
            if node[4] is not None:
                exec_stmt(node[4], Env(env, env.this, 'block'), ctx)
        return
    if kind == 'switch':
        disc = evaluate(node[1], env, ctx)
        switch_env = Env(env, env.this, 'block')
        matched = False
        for case in node[2]:
            if not matched and case[0] == 'case':
                if strict_equals(disc, evaluate(case[1], switch_env, ctx)):
                    matched = True
            if matched:
                try:
                    for st in case[2]:
                        exec_stmt(st, switch_env, ctx)
                except JSBreak:
                    return
                continue
        if not matched:
            for case in node[2]:
                if case[0] == 'default':
                    try:
                        for st in case[2]:
                            exec_stmt(st, switch_env, ctx)
                    except JSBreak:
                        return
        return
    if kind == 'class':
        exec_class(node, env, ctx)
        return
    if kind == 'label':
        try:
            exec_stmt(node[2], env, ctx)
        except JSBreak as b:
            if b.label == node[1]:
                return
            raise
        except JSContinue as c:
            if c.label == node[1]:
                return
            raise
        return
    if kind == 'import':
        exec_import(node, env, ctx)
        return
    if kind == 'exportnames':
        return
    if kind == 'exportdecl':
        exec_stmt(node[2], env, ctx)
        return
    if kind == 'exportdefault':
        evaluate(node[1], env, ctx)
        return
    if kind == 'exportexpr':
        evaluate(node[1], env, ctx)
        return
    raise JSThrow(make_error_object('SyntaxError', 'unsupported statement'))


def assign_target_from_expr(node, key, env, ctx):
    ref = eval_ref(node, env, ctx)
    set_ref(ref, key)


def exec_class(node, env, ctx):
    _, name, parent, members = node
    parent_val = None
    if parent is not None:
        parent_val = evaluate(parent, env, ctx)
    proto = JSObject()
    ctor = None
    static_obj = JSObject()
    for m in members:
        kind, key, params, body, is_static, computed = m
        if kind == 'field':
            continue
        target = static_obj if is_static else proto
        fn = JSUserFunc(key[1] if key[0] == 'id' else '', params, body, env,
                        False)
        set_property(target, eval_key(key, env, ctx, computed), fn)
        if not is_static and (key[0] == 'id' and key[1] == 'constructor'):
            ctor = fn
    if ctor is None:
        ctor = JSNativeFunc('constructor', lambda ctx, this, args: this)
    ctor.props['prototype'] = proto
    proto.props['constructor'] = ctor
    ctor.proto = getattr(parent_val, 'props', {}).get('prototype') \
        if isinstance(parent_val, (JSObject, JSUserFunc, JSNativeFunc)) \
        else None
    if name:
        env.declare(name, ctor)
    return ctor


def exec_import(node, env, ctx):
    _, default, names, src = node
    mod = ctx.load_module(src)
    if default is not None:
        env.declare(default, get_property(mod, 'default'))
    for name, alias in names:
        if name == '*':
            env.declare(alias, mod)
        else:
            env.declare(alias, get_property(mod, name))
