def get_property(obj, name):
    if obj is None or obj is UNDEF:
        raise JSThrow(make_error_object(
            'TypeError', "Cannot read properties of %s (reading '%s')" %
            ('null' if obj is NULL else 'undefined', name)))
    if isinstance(obj, JSProxy):
        return obj.get(str(name))
    if isinstance(obj, (JSObject, JSArray, JSCallable, JSRegExp, JSMap,
                        JSSet)):
        return obj.get(str(name))
    if isinstance(obj, str):
        return get_string_prop(obj, str(name))
    if isinstance(obj, (int, float)):
        return get_number_prop(obj, str(name))
    if isinstance(obj, bool):
        return get_boolean_prop(str(name))
    if obj is NULL or obj is UNDEF:
        return UNDEF
    return UNDEF


def set_property(obj, name, value):
    if isinstance(obj, JSProxy):
        return obj.set(str(name), value)
    if isinstance(obj, (JSObject, JSArray, JSCallable, JSRegExp, JSMap,
                        JSSet)):
        obj.set(str(name), value)
        return
    return


def has_property(obj, name):
    if isinstance(obj, JSProxy):
        return obj.has(str(name))
    if isinstance(obj, (JSObject, JSArray, JSCallable, JSRegExp, JSMap,
                        JSSet)):
        return obj.has(str(name))
    if isinstance(obj, str):
        return str(name) in ('length', 'constructor') or \
            str(name).isdigit() and int(str(name)) < len(obj)
    if isinstance(obj, (int, float, bool)):
        return str(name) in ('toFixed', 'toString', 'valueOf')
    return False


def own_keys(obj):
    if isinstance(obj, JSProxy):
        return obj.keys()
    if isinstance(obj, JSObject):
        return list(obj.props.keys())
    if isinstance(obj, JSArray):
        return obj.keys()
    if isinstance(obj, JSCallable):
        return obj.keys()
    if isinstance(obj, JSMap):
        return []
    if isinstance(obj, JSSet):
        return []
    if isinstance(obj, str):
        return [str(i) for i in range(len(obj))]
    return []


def get_string_prop(s, name):
    if name == 'length':
        return len(s)
    if name.isdigit():
        i = int(name)
        return s[i] if i < len(s) else UNDEF
    return get_string_method(s, name)


def get_number_prop(v, name):
    return get_number_method(v, name)


def get_boolean_prop(v, name):
    return get_boolean_method(name)


def call_function(fn, this, args, ctx=None, new_target=False):
    if isinstance(fn, (JSNativeFunc, JSUserFunc, JSCallable)):
        return fn.call(ctx, this, args)
    raise JSThrow(make_error_object('TypeError', '%s is not a function' %
                                    to_string(fn)))


# ----------------------------------------------------------------------
# evaluation
# ----------------------------------------------------------------------

def evaluate(node, env, ctx):
    kind = node[0]
    if kind == 'num':
        return node[1]
    if kind == 'str':
        return node[1]
    if kind == 'regex':
        return make_regex(node[1], node[2])
    if kind == 'const':
        return node[1]
    if kind == 'id':
        name = node[1]
        e = env.lookup(name)
        if e is not None:
            return e.vars[name]
        g = ctx.globals
        if name in g.vars:
            return g.vars[name]
        raise JSThrow(make_error_object('ReferenceError',
                                        '%s is not defined' % name))
    if kind == 'this':
        return env.this
    if kind == 'member':
        obj = evaluate(node[1], env, ctx)
        if node[3]:
            if obj is None or obj is UNDEF:
                return UNDEF
        return get_property(obj, node[2])
    if kind == 'optcall':
        obj = evaluate(node[1], env, ctx)
        if obj is None or obj is UNDEF:
            return UNDEF
        args = eval_args(node[2], env, ctx)
        fn = obj
        return call_function(fn, obj, args, ctx)
    if kind == 'index':
        obj = evaluate(node[1], env, ctx)
        idx = evaluate(node[2], env, ctx)
        return get_property(obj, index_key(idx))
    if kind == 'optindex':
        obj = evaluate(node[1], env, ctx)
        if obj is None or obj is UNDEF:
            return UNDEF
        idx = evaluate(node[2], env, ctx)
        return get_property(obj, index_key(idx))
    if kind == 'call':
        callee = node[1]
        if callee[0] == 'member':
            obj = evaluate(callee[1], env, ctx)
            if callee[3] and (obj is None or obj is UNDEF):
                return UNDEF
            fn = get_property(obj, callee[2])
            args = eval_args(node[2], env, ctx)
            if not is_callable(fn):
                name = callee[2]
                desc = to_string(to_property_desc(obj, name))
                raise JSThrow(make_error_object(
                    'TypeError', '%s is not a function' % name))
            return call_function(fn, obj, args, ctx)
        if callee[0] == 'index':
            obj = evaluate(callee[1], env, ctx)
            idx = evaluate(callee[2], env, ctx)
            fn = get_property(obj, index_key(idx))
            args = eval_args(node[2], env, ctx)
            return call_function(fn, obj, args, ctx)
        fn = evaluate(callee, env, ctx)
        args = eval_args(node[2], env, ctx)
        this = UNDEF
        if callee[0] == 'id':
            pass
        return call_function(fn, this, args, ctx)
    if kind == 'new':
        ctor = evaluate(node[1], env, ctx)
        args = eval_args(node[2], env, ctx)
        return construct(ctor, args, ctx)
    if kind == 'object':
        return eval_object(node[1], env, ctx)
    if kind == 'array':
        return eval_array(node[1], env, ctx)
    if kind == 'func':
        return JSUserFunc(node[4] if len(node) > 4 else '',
                          node[1], node[2], env, node[3], env.this)
    if kind == 'tmpl':
        return eval_template(node[1], env, ctx)
    if kind == 'tagtmpl':
        fn = evaluate(node[1], env, ctx)
        strings, raw = template_strings(node[2])
        values = []
        for part in node[2]:
            if isinstance(part, tuple):
                values.append(evaluate(Parser(tokenize(part[1])).parse_expr()
                                       if False else parse_one(part[1]),
                                       env, ctx))
        return call_function(fn, strings, [strings] + values, ctx)
    if kind == 'binop':
        return eval_binop(node, env, ctx)
    if kind == 'unary':
        return eval_unary(node, env, ctx)
    if kind == 'postfix':
        return eval_postfix(node, env, ctx)
    if kind == 'assign':
        return eval_assign(node, env, ctx)
    if kind == 'cond':
        if to_boolean(evaluate(node[1], env, ctx)):
            return evaluate(node[2], env, ctx)
        return evaluate(node[3], env, ctx)
    if kind == 'seq':
        evaluate(node[1], env, ctx)
        return evaluate(node[2], env, ctx)
    if kind == 'spread':
        return evaluate(node[1], env, ctx)
    if kind == 'super':
        return UNDEF
    raise JSThrow(make_error_object('SyntaxError', 'unsupported expression'))


def parse_one(src):
    from .parse import Parser, tokenize
    return Parser(tokenize(src)).parse_expression()


def to_property_desc(obj, name):
    try:
        return get_property(obj, name)
    except JSThrow:
        return UNDEF


def index_key(idx):
    if isinstance(idx, (int, float)):
        return to_string(idx)
    return to_string(idx)


def eval_args(arg_nodes, env, ctx):
    args = []
    for a in arg_nodes:
        if a[0] == 'spread':
            v = evaluate(a[1], env, ctx)
            args.extend(to_list(v))
        else:
            args.append(evaluate(a, env, ctx))
    return args


def to_list(v):
    if isinstance(v, JSArray):
        return list(v.items)
    if isinstance(v, str):
        return list(v)
    if isinstance(v, JSMap):
        return [JSArray([k, val]) for k, val in v.entries]
    if isinstance(v, JSSet):
        return list(v.items)
    if v is UNDEF or v is NULL:
        raise JSThrow(make_error_object(
            'TypeError', 'undefined is not iterable'))
    if isinstance(v, JSObject):
        it = get_property(v, JSSymbolIteratorKey)
        if it is not UNDEF and is_callable(it):
            res = call_function(it, v, [])
            out = []
            while True:
                nxt = call_function(get_property(res, 'next'), res, [])
                done = to_boolean(get_property(nxt, 'done'))
                if done:
                    break
                out.append(get_property(nxt, 'value'))
            return out
        return []
    return [v]


JSSymbolIteratorKey = JSObject({'__symbol__': True, 'description':
                                'Symbol.iterator'})


def eval_object(props, env, ctx):
    obj = JSObject(proto=None)
    for prop in props:
        kind = prop[0]
        if kind == 'spread':
            src = evaluate(prop[1], env, ctx)
            for k in own_keys(src):
                set_property(obj, k, get_property(src, k))
            continue
        if kind == 'method':
            key, params, body, is_static, computed = (prop[1], prop[2],
                                                      prop[3], False, prop[4])
            fn = JSUserFunc(key[1] if key[0] == 'id' else '', params, body,
                            env, False)
            name = eval_key(key, env, ctx, computed)
            set_property(obj, name, fn)
            continue
        _, key, value_node, _, computed = prop
        name = eval_key(key, env, ctx, computed)
        set_property(obj, name, evaluate(value_node, env, ctx))
    return obj


def eval_key(key, env, ctx, computed):
    if key[0] == 'expr':
        return to_string(evaluate(key[1], env, ctx))
    if key[0] == 'str':
        return key[1]
    if key[0] == 'num':
        return to_string(key[1])
    return key[1]


def eval_array(elems, env, ctx):
    items = []
    for e in elems:
        if e[0] == 'hole':
            items.append(UNDEF)
        elif e[0] == 'spread':
            items.extend(to_list(evaluate(e[1], env, ctx)))
        else:
            items.append(evaluate(e, env, ctx))
    return JSArray(items)


def template_strings(parts):
    strings = []
    raw = []
    for i, part in enumerate(parts):
        if isinstance(part, tuple):
            strings.append('')
        else:
            strings.append(part)
            raw.append(part)
    if not any(isinstance(p, tuple) for p in parts):
        raw = list(strings)
    return JSArray(strings), JSArray(raw)


def eval_template(parts, env, ctx):
    out = []
    for part in parts:
        if isinstance(part, tuple):
            v = evaluate(parse_one(part[1]), env, ctx)
            out.append(to_string(v))
        else:
            out.append(part)
    return ''.join(out)


def eval_binop(node, env, ctx):
    op = node[1]
    if op == '&&':
        left = evaluate(node[2], env, ctx)
        return evaluate(node[3], env, ctx) if to_boolean(left) else left
    if op == '||':
        left = evaluate(node[2], env, ctx)
        return left if to_boolean(left) else evaluate(node[3], env, ctx)
    if op == '??':
        left = evaluate(node[2], env, ctx)
        if left is UNDEF or left is NULL:
            return evaluate(node[3], env, ctx)
        return left
    left = evaluate(node[2], env, ctx)
    right = evaluate(node[3], env, ctx)
    return apply_binop(op, left, right)


def apply_binop(op, left, right):
    if op == '+':
        lp = to_primitive(left)
        rp = to_primitive(right)
        if isinstance(lp, str) or isinstance(rp, str):
            return to_string(lp) + to_string(rp)
        return to_number(lp) + to_number(rp)
    if op == '-':
        return to_number(left) - to_number(right)
    if op == '*':
        return to_number(left) * to_number(right)
    if op == '/':
        ln, rn = to_number(left), to_number(right)
        if rn == 0:
            if ln == 0 or ln != ln:
                return float('nan')
            return float('inf') if (ln > 0) == (rn == 0 and rn == 0) else \
                float('nan')
        return ln / rn
    if op == '%':
        ln, rn = to_number(left), to_number(right)
        if rn == 0 or ln != ln or rn != rn:
            return float('nan')
        return ln - rn * int(ln / rn) if ln >= 0 else ln - rn * -int(-ln / rn)
    if op == '**':
        return to_number(left) ** to_number(right)
    if op in ('==', '!='):
        res = equals(left, right)
        return res if op == '==' else not res
    if op in ('===', '!=='):
        res = strict_equals(left, right)
        return res if op == '===' else not res
    if op == '<':
        return compare_lt(left, right, False)
    if op == '>':
        return compare_lt(right, left, False)
    if op == '<=':
        return not compare_lt(right, left, True)
    if op == '>=':
