    if op == 'in':
        return has_property(right, to_string(left))
    if op == '&':
        return to_int32(left) & to_int32(right)
    if op == '|':
        return to_int32(left) | to_int32(right)
    if op == '^':
        return to_int32(left) ^ to_int32(right)
    if op == '<<':
        return to_int32(left) << (to_uint32(right) & 31)
    if op == '>>':
        return to_int32(left) >> (to_uint32(right) & 31)
    if op == '>>>':
        return to_uint32(left) >> (to_uint32(right) & 31)
