def to_int32(v):
    n = to_number(v)
    if n != n:
        return 0
    if n in (float('inf'), float('-inf')):
        return 0
    n = int(n)
    n &= 0xFFFFFFFF
    if n >= 0x80000000:
        n -= 0x100000000
    return n


def to_uint32(v):
    n = to_number(v)
    if n != n:
        return 0
    if n in (float('inf'), float('-inf')):
