        raw = list(strings)
    return JSArray(strings), JSArray(raw)


def eval_template(parts, env, ctx):
    out = []
    for part in parts:
        if isinstance(part, tuple):
            v = evaluate(parse_one(part[1]), env, ctx)
            out.append(to_string(v))
        else:
            out.append(part)
    return ''.join(out)


def eval_binop(node, env, ctx):
    op = node[1]
    if op == '&&':
        left = evaluate(node[2], env, ctx)
        return evaluate(node[3], env, ctx) if to_boolean(left) else left
    if op == '||':
        left = evaluate(node[2], env, ctx)
        return left if to_boolean(left) else evaluate(node[3], env, ctx)
    if op == '??':
        left = evaluate(node[2], env, ctx)
        if left is UNDEF or left is NULL:
            return evaluate(node[3], env, ctx)
        return left
    left = evaluate(node[2], env, ctx)
    right = evaluate(node[3], env, ctx)
    return apply_binop(op, left, right)


def apply_binop(op, left, right):
    if op == '+':
        lp = to_primitive(left)
        rp = to_primitive(right)
        if isinstance(lp, str) or isinstance(rp, str):
            return to_string(lp) + to_string(rp)
        return to_number(lp) + to_number(rp)
    if op == '-':
        return to_number(left) - to_number(right)
    if op == '*':
        return to_number(left) * to_number(right)
    if op == '/':
        ln, rn = to_number(left), to_number(right)
        if rn == 0:
            if ln == 0 or ln != ln:
                return float('nan')
            return float('inf') if (ln > 0) == (rn == 0 and rn == 0) else \
                float('nan')
        return ln / rn
    if op == '%':
        ln, rn = to_number(left), to_number(right)
        if rn == 0 or ln != ln or rn != rn:
            return float('nan')
        return ln - rn * int(ln / rn) if ln >= 0 else ln - rn * -int(-ln / rn)
    if op == '**':
        return to_number(left) ** to_number(right)
    if op in ('==', '!='):
        res = equals(left, right)
        return res if op == '==' else not res
    if op in ('===', '!=='):
        res = strict_equals(left, right)
        return res if op == '===' else not res
    if op == '<':
        return compare_lt(left, right, False)
    if op == '>':
        return compare_lt(right, left, False)
    if op == '<=':
        return not compare_lt(right, left, True)
    if op == '>=':
        return not compare_lt(left, right, True)
    if op == 'instanceof':
        return js_instanceof(left, right)
    if op == 'in':
        return has_property(right, to_string(left))
    if op == '&':
        return to_int32(left) & to_int32(right)
    if op == '|':
        return to_int32(left) | to_int32(right)
    if op == '^':
        return to_int32(left) ^ to_int32(right)
    if op == '<<':
        return to_int32(left) << (to_uint32(right) & 31)
    if op == '>>':
        return to_int32(left) >> (to_uint32(right) & 31)
    if op == '>>>':
        return to_uint32(left) >> (to_uint32(right) & 31)
    raise JSThrow(make_error_object('SyntaxError', 'unsupported operator'))


def compare_lt(a, b, equal_or_nan):
    ap = to_primitive(a, 'number')
    bp = to_primitive(b, 'number')
    if isinstance(ap, str) and isinstance(bp, str):
        return ap < bp
    an, bn = to_number(ap), to_number(bp)
    if an != an or bn != bn:
        return False
    return an < bn


def js_instanceof(left, right):
    if isinstance(right, JSUserFunc):
        proto = get_property(right, 'prototype')
    else:
        proto = get_property(right, 'prototype')
    obj = left
    while isinstance(obj, (JSObject, JSArray)):
        if obj.proto is proto:
            return True
        obj = obj.proto
    return False


def to_int32(v):
    n = to_number(v)
    if n != n:
        return 0
    if n in (float('inf'), float('-inf')):
        return 0
    n = int(n)
    n &= 0xFFFFFFFF
    if n >= 0x80000000:
        n -= 0x100000000
    return n


def to_uint32(v):
    n = to_number(v)
    if n != n:
        return 0
    if n in (float('inf'), float('-inf')):
        return 0
    return int(n) & 0xFFFFFFFF


def eval_unary(node, env, ctx):
    op = node[1]
    if op == 'typeof':
        operand = node[2]
        if operand[0] == 'id':
            e = env.lookup(operand[1])
            if e is None and operand[1] not in ctx.globals.vars:
                return 'undefined'
        return typeof(evaluate(operand, env, ctx))
    if op == 'void':
        evaluate(node[2], env, ctx)
        return UNDEF
    if op == 'delete':
        target = node[2]
        if target[0] == 'member':
            obj = evaluate(target[1], env, ctx)
            try:
                del obj.props[target[2]]
            except Exception:
                pass
            return True
        if target[0] == 'index':
            obj = evaluate(target[1], env, ctx)
            key = index_key(evaluate(target[2], env, ctx))
            try:
                del obj.props[key]
            except Exception:
                pass
            return True
        return True
    val = evaluate(node[2], env, ctx)
    if op == '!':
        return not to_boolean(val)
    if op == '-':
        return -to_number(val)
    if op == '+':
        return to_number(val)
    if op == '~':
        return ~to_int32(val)
    if op == '++':
        ref = eval_ref(node[2], env, ctx)
        new = to_number(get_ref(ref)) + 1
        set_ref(ref, new)
        return new
    if op == '--':
        ref = eval_ref(node[2], env, ctx)
        new = to_number(get_ref(ref)) - 1
        set_ref(ref, new)
        return new
    if op == 'await':
        return val
    raise JSThrow(make_error_object('SyntaxError', 'unsupported operator'))


def eval_postfix(node, env, ctx):
    op = node[1]
    ref = eval_ref(node[2], env, ctx)
    old = get_ref(ref)
    new = to_number(old) + (1 if op == '++' else -1)
    set_ref(ref, new)
    return old


def eval_ref(node, env, ctx):
    if node[0] == 'id':
        return ('env', node[1], env)
    if node[0] == 'member':
        obj = evaluate(node[1], env, ctx)
        return ('prop', obj, node[2])
    if node[0] == 'index':
        obj = evaluate(node[1], env, ctx)
        key = index_key(evaluate(node[2], env, ctx))
        return ('prop', obj, key)
    raise JSThrow(make_error_object('SyntaxError', 'invalid left-hand side'))


def get_ref(ref):
    if ref[0] == 'env':
        return ref[2].get(ref[1]) if ref[2].lookup(ref[1]) is not None \
            else ctx_global_get(ref[1])
    return get_property(ref[1], ref[2])


def ctx_global_get(name):
    raise JSThrow(make_error_object('ReferenceError',
                                    '%s is not defined' % name))


def set_ref(ref, value):
    if ref[0] == 'env':
        if ref[2].lookup(ref[1]) is not None:
            ref[2].set(ref[1], value)
        return
    set_property(ref[1], ref[2], value)


def eval_assign(node, env, ctx):
    op = node[1]
    target = node[2]
    value_node = node[3]
    if op == '=':
        if target[0] in ('objpat', 'arrpat'):
            value = evaluate(value_node, env, ctx)
            assign_destructure(target, value, env, ctx)
            return value
        ref = eval_ref(target, env, ctx)
        value = evaluate(value_node, env, ctx)
        set_ref(ref, value)
        return value
    ref = eval_ref(target, env, ctx)
    old = get_ref(ref)
    value = evaluate(value_node, env, ctx)
    if op == '&&=':
        if not to_boolean(old):
            return old
        new = value
    elif op == '||=':
        if to_boolean(old):
            return old
        new = value
    elif op == '??=':
        if old is not UNDEF and old is not NULL:
            return old
        new = value
    else:
        new = apply_binop(op[:-1], old, value)
    set_ref(ref, new)
    return new


def assign_destructure(pattern, value, env, ctx):
    if pattern[0] == 'arrpat':
        items = to_list(value)
        for i, (_, name, default, _) in enumerate(pattern[1]):
            v = items[i] if i < len(items) else UNDEF
            if v is UNDEF and default is not None:
                v = evaluate(default, env, ctx)
            assign_target(name, v, env, ctx)
        return
    for key, name, default, _ in pattern[1]:
        if key is None:
            v = get_property(value, name)
        elif key[0] == 'expr':
            v = get_property(value, to_string(evaluate(key[1], env, ctx)))
        else:
            v = get_property(value, key[1])
        if v is UNDEF and default is not None:
            v = evaluate(default, env, ctx)
        assign_target(name, v, env, ctx)


def assign_target(name, value, env, ctx):
    if isinstance(name, str):
        e = env.lookup(name)
        if e is not None:
            e.vars[name] = value
        else:
            ctx.globals.vars[name] = value
    else:
        evaluate(('assign', '=', name, ('const', value)), env, ctx)


