    if kind == 'empty':
        return
    if kind == 'var':
        for kind2, name, init in node[1]:
            if isinstance(name, str):
                value = UNDEF
                if init is not None:
                    value = evaluate(init, env, ctx)
                env.declare(name, value)
            else:
                value = evaluate(init, env, ctx) if init is not None else UNDEF
                assign_destructure(name, value, env, ctx)
