    if kind == 'for':
        loop_env = Env(env, env.this, 'block')
        if node[1] is not None:
            exec_stmt(node[1], loop_env, ctx)
        while True:
            if node[2] is not None and not to_boolean(
                    evaluate(node[2], loop_env, ctx)):
                break
            try:
                exec_stmt(node[4], loop_env, ctx)
            except JSBreak:
                break
            except JSContinue:
                pass
            if node[3] is not None:
                evaluate(node[3], loop_env, ctx)
        return
    if kind == 'forin' or kind == 'forof':
        loop_env = Env(env, env.this, 'block')
        target = evaluate(node[2], env, ctx)
        if kind == 'forin':
            keys = own_keys(target)
            if isinstance(target, JSArray):
                keys = [k for k in keys]
        else:
            keys = to_list(target)
        for key in keys:
            decl = node[1]
            if decl is None:
                continue
            if decl[0] == 'var':
                for _, name, _ in decl[1]:
                    assign_target(name, key, loop_env, ctx)
            elif decl[0] == 'expr':
                assign_target_from_expr(decl[1], key, loop_env, ctx)
            else:
                assign_target_from_expr(decl, key, loop_env, ctx)
            try:
                exec_stmt(node[3], loop_env, ctx)
            except JSBreak:
                break
            except JSContinue:
                continue
        return
    if kind == 'while':
        while to_boolean(evaluate(node[1], env, ctx)):
            try:
                exec_stmt(node[2], env, ctx)
            except JSBreak:
                break
            except JSContinue:
                continue
        return
    if kind == 'dowhile':
        while True:
            try:
                exec_stmt(node[2], env, ctx)
            except JSBreak:
                break
            except JSContinue:
                pass
            if not to_boolean(evaluate(node[1], env, ctx)):
                break
        return
    if kind == 'return':
        value = evaluate(node[1], env, ctx) if node[1] is not None else UNDEF
        raise JSReturn(value)
    if kind == 'break':
        raise JSBreak(node[1])
    if kind == 'continue':
        raise JSContinue(node[1])
    if kind == 'throw':
        raise JSThrow(evaluate(node[1], env, ctx))
    if kind == 'try':
        try:
            try:
                exec_stmt(node[1], Env(env, env.this, 'block'), ctx)
            except JSThrow as t:
                if node[3] is None:
                    raise
                cenv = Env(env, env.this, 'block')
                if node[2] is not None:
                    cenv.declare(node[2], t.value)
                exec_stmt(node[3], cenv, ctx)
        finally:
            if node[4] is not None:
                exec_stmt(node[4], Env(env, env.this, 'block'), ctx)
        return
    if kind == 'switch':
        disc = evaluate(node[1], env, ctx)
        switch_env = Env(env, env.this, 'block')
        matched = False
        for case in node[2]:
            if not matched and case[0] == 'case':
                if strict_equals(disc, evaluate(case[1], switch_env, ctx)):
                    matched = True
            if matched:
                try:
                    for st in case[2]:
                        exec_stmt(st, switch_env, ctx)
                except JSBreak:
                    return
                continue
        if not matched:
            for case in node[2]:
                if case[0] == 'default':
                    try:
                        for st in case[2]:
                            exec_stmt(st, switch_env, ctx)
                    except JSBreak:
                        return
        return
    if kind == 'class':
        exec_class(node, env, ctx)
        return
    if kind == 'label':
        try:
            exec_stmt(node[2], env, ctx)
        except JSBreak as b:
            if b.label == node[1]:
                return
            raise
        except JSContinue as c:
            if c.label == node[1]:
                return
            raise
        return
    if kind == 'import':
        exec_import(node, env, ctx)
        return
    if kind == 'exportnames':
        return
    if kind == 'exportdecl':
        exec_stmt(node[2], env, ctx)
        return
    if kind == 'exportdefault':
        evaluate(node[1], env, ctx)
        return
    if kind == 'exportexpr':
        evaluate(node[1], env, ctx)
        return
    raise JSThrow(make_error_object('SyntaxError', 'unsupported statement'))


def assign_target_from_expr(node, key, env, ctx):
    ref = eval_ref(node, env, ctx)
    set_ref(ref, key)


def exec_class(node, env, ctx):
    _, name, parent, members = node
    parent_val = None
    if parent is not None:
        parent_val = evaluate(parent, env, ctx)
    proto = JSObject()
    ctor = None
