def number_to_string(ctx, this, args):
    radix = int(to_number(args[0])) if args and args[0] is not UNDEF else 10
    n = to_number(this)
    if radix == 10:
        return to_string(n)
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = abs(int(n))
    out = ''
    while n:
        out = digits[n % radix] + out
        n //= radix
    return ('-' if neg else '') + (out or '0')


