def _round(n):
    if n != n:
        return float('nan')
    f = math.floor(n)
    if n - f >= 0.5:
        return f + 1
    return f


def _max(args):
    best = float('-inf')
    for a in args:
        n = to_number(a)
        if n != n:
            return float('nan')
        if n > best:
            best = n
    return best


def _min(args):
    best = float('inf')
    for a in args:
        n = to_number(a)
        if n != n:
            return float('nan')
        if n < best:
            best = n
    return best


def _sign(n):
    if n != n:
        return float('nan')
    return 1 if n > 0 else (-1 if n < 0 else n)


def _clz32(args):
    n = to_uint32(args[0]) if args else 0
    count = 0
    for i in range(31, -1, -1):
        if n & (1 << i):
            break
        count += 1
    return count


