def fmt_value(v, depth=0):
    if v is UNDEF:
        return 'undefined'
    if v is NULL:
        return 'null'
    if isinstance(v, str):
        return v
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, (int, float)):
        return to_string(v)
    if isinstance(v, JSArray):
        if depth > 2:
            return '[Array]'
        return '[ ' + ', '.join(fmt_value(x, depth + 1)
                                for x in v.items) + ' ]'
    if isinstance(v, JSObject):
        if depth > 2:
            return '[Object]'
        return '{ ' + ', '.join('%s: %s' % (k, fmt_value(
            get_property(v, k), depth + 1)) for k in own_keys(v)) + ' }'
    if isinstance(v, (JSNativeFunc, JSUserFunc)):
        return '[Function: %s]' % (v.name or '(anonymous)')
    return to_string(v)
