    def method(ctx, this, args):
        s = to_string(this)
        return apply_string_method(ctx, name, s, this, args)
    return JSNativeFunc(name, method)


def apply_string_method(ctx, name, s, this, args):
    def arg(i, default=None):
        return args[i] if len(args) > i and args[i] is not UNDEF else default
    if name == 'charAt':
        i = int(to_number(arg(0, 0)))
        return s[i] if 0 <= i < len(s) else ''
    if name == 'charCodeAt':
        i = int(to_number(arg(0, 0)))
        return ord(s[i]) if 0 <= i < len(s) else float('nan')
    if name == 'codePointAt':
        i = int(to_number(arg(0, 0)))
        return ord(s[i]) if 0 <= i < len(s) else UNDEF
    if name == 'at':
        i = int(to_number(arg(0, 0)))
        if i < 0:
            i += len(s)
        return s[i] if 0 <= i < len(s) else UNDEF
    if name == 'slice':
        start = slice_index(arg(0), len(s), 0)
        end = slice_index(arg(1), len(s), len(s))
        return s[start:end]
    if name == 'substring':
        start = int(to_number(arg(0, 0))) if arg(0, 0) is not None else 0
        end = int(to_number(arg(1, len(s)))) if arg(1, len(s)) is not None \
            else len(s)
        start = max(0, min(start, len(s)))
        end = max(0, min(end, len(s)))
        if start > end:
            start, end = end, start
        return s[start:end]
    if name == 'substr':
        start = int(to_number(arg(0, 0))) if arg(0, 0) is not None else 0
        if start < 0:
            start = max(0, len(s) + start)
        length = int(to_number(arg(1, len(s)))) if arg(1, len(s)) is not None \
            else len(s)
        return s[start:start + max(0, length)]
    if name == 'toUpperCase':
        return s.upper()
    if name == 'toLowerCase':
        return s.lower()
    if name == 'trim':
        return s.strip(' \t\n\r\f\v')
    if name == 'trimStart':
        return s.lstrip(' \t\n\r\f\v')
    if name == 'trimEnd':
        return s.rstrip(' \t\n\r\f\v')
    if name == 'indexOf':
        needle = to_string(arg(0, 'undefined'))
        start = int(to_number(arg(1, 0)))
        return s.find(needle, max(0, start))
    if name == 'lastIndexOf':
        needle = to_string(arg(0, 'undefined'))
        return s.rfind(needle)
    if name == 'includes':
        needle = to_string(arg(0, 'undefined'))
        return needle in s
    if name == 'startsWith':
        needle = to_string(arg(0, 'undefined'))
        pos = int(to_number(arg(1, 0)))
        return s.startswith(needle, pos)
    if name == 'endsWith':
        needle = to_string(arg(0, 'undefined'))
        pos = int(to_number(arg(1, len(s))))
        return s[:pos].endswith(needle)
    if name == 'split':
        sep = arg(0, UNDEF)
        limit = arg(1)
        if sep is UNDEF:
            out = [s]
        elif isinstance(sep, JSRegExp):
            pattern, flags = js_compile(sep.source, sep.flags)
            out = pattern.split(s) if pattern.pattern else list(s)
        else:
            sepstr = to_string(sep)
            out = s.split(sepstr) if sepstr != '' else list(s)
        if limit is not None:
            lim = int(to_number(limit))
            out = out[:lim] if lim >= 0 else []
        return JSArray(out)
    if name == 'replace' or name == 'replaceAll':
        needle = arg(0)
        rep = arg(1)
        all_ = (name == 'replaceAll')
        if isinstance(needle, JSRegExp):
            pattern, flags = js_compile(needle.source, needle.flags)
            count = 0 if (needle.global_flag or all_) else 1

            def repl(m):
                if is_callable(rep):
                    return to_string(call_function2(rep, UNDEF,
                                                    [match_obj(m)] +
                                                    list(m.groups()) + [0, s]))
                return expand_replacement(to_string(rep), m)
            return pattern.sub(repl, s, count=count)
        needle_str = to_string(needle)
        if is_callable(rep):
            def repl2(m):
                return to_string(call_function2(rep, UNDEF,
                                                [m.group(0), 0, s]))
            if all_:
                out = []
                if needle_str == '':
                    return s
                i = 0
                while True:
                    j = s.find(needle_str, i)
                    if j < 0:
                        out.append(s[i:])
                        break
                    out.append(s[i:j])
                    out.append(repl2(type('M', (), {
                        'group': (lambda *a: needle_str)})()))
                    i = j + len(needle_str)
                return ''.join(out)
            j = s.find(needle_str)
            if j < 0:
                return s
            return s[:j] + repl2(None) + s[j + len(needle_str):]
        rep_str = to_string(rep)
        if needle_str == '':
            return rep_str + s if all_ else rep_str + s
        return s.replace(needle_str, rep_str) if all_ else \
            s.replace(needle_str, rep_str, 1)
    if name == 'repeat':
        n = int(to_number(arg(0, 0)))
        return s * n
    if name == 'padStart':
        n = int(to_number(arg(0, 0)))
        pad = to_string(arg(1, ' '))
        if len(s) >= n:
            return s
        fill = (pad * (n - len(s) + max(1, len(pad))))[:n - len(s)]
        return fill + s
    if name == 'padEnd':
        n = int(to_number(arg(0, 0)))
        pad = to_string(arg(1, ' '))
        if len(s) >= n:
            return s
        fill = (pad * (n - len(s) + max(1, len(pad))))[:n - len(s)]
        return s + fill
    if name == 'concat':
        return s + ''.join(to_string(a) for a in args)
    if name == 'toString' or name == 'valueOf':
        return s
    if name == 'localeCompare':
        other = to_string(arg(0, ''))
        return -1 if s < other else (1 if s > other else 0)
    if name == 'normalize':
        import unicodedata
        return unicodedata.normalize(to_string(arg(0, 'NFC')), s)
    if name == 'match':
        needle = arg(0)
        if isinstance(needle, JSRegExp):
            pattern, flags = js_compile(needle.source, needle.flags)
            if needle.global_flag:
                out = [m.group(0) for m in pattern.finditer(s)]
                if not out:
                    return NULL
                return JSArray(out)
            m = pattern.search(s)
            if not m:
                return NULL
            return match_obj(m)
        return apply_string_method(ctx, 'match', s, this,
                                   [make_regex(to_string(needle), '')])
    if name == 'matchAll':
        needle = arg(0)
        pattern, flags = js_compile(needle.source, needle.flags)
        out = [match_obj(m) for m in pattern.finditer(s)]
        return iterator_of(JSArray(out))
    if name == 'search':
        needle = arg(0)
        if isinstance(needle, JSRegExp):
            pattern, flags = js_compile(needle.source, needle.flags)
            m = pattern.search(s)
            return m.start() if m else -1
        pattern, flags = js_compile(to_string(needle), '')
        m = pattern.search(s)
        return m.start() if m else -1
    if name == 'localeCompare':
        return 0
    if name == 'raw':
        return s
    if name == 'replace':
        pass
    raise JSThrow(make_error_object('TypeError', '%s is not a function' %
                                    name))


def slice_index(value, length, default):
    if value is None:
        return default
    n = int(to_number(value))
    if n < 0:
        n += length
    return max(0, min(n, length))


def match_obj(m):
    groups = list(m.groups())
    out = JSArray([m.group(0)] + groups)
    set_property(out, 'index', m.start())
    set_property(out, 'input', m.string)
    set_property(out, 'groups', JSObject())
    return out


def expand_replacement(template, m):
    out = []
    i = 0
    while i < len(template):
        c = template[i]
        if c == '$' and i + 1 < len(template):
            nxt = template[i + 1]
            if nxt == '&':
                out.append(m.group(0))
                i += 2
                continue
            if nxt == '`':
                out.append(m.string[:m.start()])
                i += 2
                continue
            if nxt == "'":
                out.append(m.string[m.end():])
                i += 2
                continue
            if nxt.isdigit():
                num = int(nxt)
                if num <= len(m.groups()):
                    g = m.group(num)
                    out.append(g if g is not None else '')
                    i += 2
                    continue
            if nxt == '$':
                out.append('$')
                i += 2
                continue
        out.append(c)
        i += 1
    return ''.join(out)


