def _is_finite(v):
    n = to_number(v)
    return n == n and n not in (float('inf'), float('-inf'))


def _parse_float(s):
    m = re.match(r'\s*[+-]?(Infinity|\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+)', s)
    if not m:
        return float('nan')
    t = m.group(1)
    if t == 'Infinity':
        return float('inf')
    return float(t)


def _parse_int(s, radix=10):
    m = re.match(r'\s*[+-]?(0[xX][0-9a-fA-F]+|[0-9]+)', s)
    if not m:
        return float('nan')
    try:
        return int(m.group(1), 16 if m.group(1).lower().startswith('0x')
                   else radix)
    except ValueError:
        return float('nan')


