def _round(n):
    if n != n:
        return float('nan')
    f = math.floor(n)
    if n - f >= 0.5:
        return f + 1
    return f


def _max(args):
    best = float('-inf')
    for a in args:
        n = to_number(a)
        if n != n:
            return float('nan')
        if n > best:
            best = n
    return best


def _min(args):
    best = float('inf')
    for a in args:
        n = to_number(a)
        if n != n:
            return float('nan')
        if n < best:
            best = n
    return best


def _sign(n):
    if n != n:
        return float('nan')
    return 1 if n > 0 else (-1 if n < 0 else n)


def _clz32(args):
    n = to_uint32(args[0]) if args else 0
    count = 0
    for i in range(31, -1, -1):
        if n & (1 << i):
            break
        count += 1
    return count


def json_stringify(ctx, this, args, indent=0, level=0):
    value = args[0] if args else UNDEF
    replacer = args[1] if len(args) > 1 else UNDEF
    space = args[2] if len(args) > 2 else UNDEF
    gap = ''
    if isinstance(space, (int, float)):
        gap = ' ' * max(0, min(int(to_number(space)), 10))
    elif isinstance(space, str):
        gap = space[:10]
    return _stringify(value, '', gap)


def _stringify(value, holder_key, gap, seen=None):
    if value is UNDEF or value is NULL:
        return 'null'
    if isinstance(value, bool):
        return 'true' if value else 'false'
    if isinstance(value, (int, float)):
        n = to_number(value)
        if n != n:
            return 'null'
        return to_string(n)
    if isinstance(value, str):
        return json_quote(value)
    if isinstance(value, JSArray):
        items = ['' if x is UNDEF else _stringify(x, str(i), gap)
                 for i, x in enumerate(value.items)]
        if not items:
            return '[]'
        if not gap:
            return '[' + ','.join(items) + ']'
        return '[\n' + gap + (',\n' + gap).join(items) + '\n]'
    if isinstance(value, JSObject):
        out = []
        for k in own_keys(value):
            v = get_property(value, k)
            if v is UNDEF:
                continue
            out.append(json_quote(k) + ':' +
                       (gap + _stringify(v, k, gap) if gap
                        else _stringify(v, k, gap)))
        if not out:
            return '{}'
        if not gap:
            return '{' + ','.join(out) + '}'
        return '{\n' + gap + (',\n' + gap).join(out) + '\n}'
    return 'undefined'


def json_quote(s):
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\f':
            out.append('\\f')
        elif o < 0x20:
            out.append('\\u%04x' % o)
        else:
            out.append(ch)
    out.append('"')
    return ''.join(out)


def json_parse(ctx, this, args):
    text = to_string(args[0]) if args else 'undefined'
    try:
        return json_to_value(text)
    except Exception:
        raise JSThrow(make_error_object(
            'SyntaxError', 'Unexpected token in JSON'))


def json_to_value(text):
    import json as _json
    data = _json.loads(text)

    def conv(d):
        if isinstance(d, dict):
            return JSObject({k: conv(v) for k, v in d.items()})
        if isinstance(d, list):
            return JSArray([conv(x) for x in d])
        return d
    return conv(data)


