    for name in ('log', 'info', 'debug', 'dir', 'trace', 'table'):
        obj.props[name] = JSNativeFunc(name, writer)
    obj.props['warn'] = JSNativeFunc('warn', writer)
    obj.props['error'] = JSNativeFunc('error', writer)
    obj.props['assert'] = JSNativeFunc(
        'assert', lambda ctx, this, args: writer(ctx, this, args)
        if args and not to_boolean(args[0]) else UNDEF)
    obj.props['time'] = JSNativeFunc('time', lambda ctx, this, args: UNDEF)
    obj.props['timeEnd'] = JSNativeFunc(
        'timeEnd', lambda ctx, this, args: writer(ctx, this, ['0ms']))
    return obj


def fmt_value(v, depth=0):
    if v is UNDEF:
        return 'undefined'
    if v is NULL:
        return 'null'
    if isinstance(v, str):
        return v
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, (int, float)):
        return to_string(v)
    if isinstance(v, JSArray):
        if depth > 2:
            return '[Array]'
        return '[ ' + ', '.join(fmt_value(x, depth + 1)
                                for x in v.items) + ' ]'
    if isinstance(v, JSObject):
        if depth > 2:
            return '[Object]'
        return '{ ' + ', '.join('%s: %s' % (k, fmt_value(
            get_property(v, k), depth + 1)) for k in own_keys(v)) + ' }'
