"""Implementation of `tree-sitter version`."""

import json
import os
import re

from ..util import colored_warning


class SemverError(Exception):
    def __init__(self, message):
        super().__init__(message)
        self.message = message


def parse_version(text):
    """Parses a semantic version string, raising SemverError with the same
    wording as the reference implementation."""
    i = 0
    n = len(text)

    def number(name):
        nonlocal i
        start = i
        while i < n and text[i].isdigit():
            i += 1
        if start == i:
            if i >= n:
                raise SemverError('unexpected end of input while parsing %s '
                                  'version number' % name)
            raise SemverError("unexpected character '%s' while parsing %s "
                              'version number' % (text[i], name))
        digits = text[start:i]
        if len(digits) > 1 and digits[0] == '0':
            raise SemverError('invalid leading zero in %s version number'
                              % name)
        try:
            value = int(digits)
        except ValueError:
            raise SemverError('value of %s version number exceeds u64::MAX'
                              % name)
        if digits == '18446744073709551616':
            raise SemverError('value of %s version number exceeds u64::MAX'
                              % name)
        return value

    major = number('major')
    if i >= n:
        raise SemverError('unexpected end of input while parsing major '
                          'version number')
    if text[i] != '.':
        raise SemverError("unexpected character '%s' after major version "
                          'number' % text[i])
    i += 1
    minor = number('minor')
    if i >= n:
        raise SemverError('unexpected end of input while parsing minor '
                          'version number')
    if text[i] != '.':
        raise SemverError("unexpected character '%s' after minor version "
                          'number' % text[i])
    i += 1
    patch = number('patch')
    pre = None
    build = None
    if i < n and text[i] == '-':
        i += 1
        start = i
        while i < n and text[i] not in '+':
            i += 1
        pre = text[start:i]
        if pre == '':
            raise SemverError('empty identifier segment in pre-release '
                              'identifier')
    if i < n and text[i] == '+':
        i += 1
        start = i
        while i < n and text[i] not in '+':
            i += 1
        build = text[start:i]
        if build == '':
            raise SemverError('empty identifier segment in build metadata')
    if i < n:
        raise SemverError("unexpected character '%s' after patch version "
                          'number' % text[i])
    return (major, minor, patch, pre, build)


def format_version(v):
    major, minor, patch, pre, build = v
    out = '%d.%d.%d' % (major, minor, patch)
    if pre:
        out += '-' + pre
    if build:
        out += '+' + build
    return out


def bump(level, version):
    major, minor, patch, pre, build = version
    if level == 'major':
        return (major + 1, 0, 0, None, build)
    if level == 'minor':
        return (major, minor + 1, 0, None, build)
    return (major, minor, patch + 1, None, build)


def find_grammar_dir(grammar_path):
    if grammar_path:
        return grammar_path
    return os.getcwd()


def run(parsed):
    path = find_grammar_dir(parsed.values.get('grammar-path'))
    config_path = os.path.join(path, 'tree-sitter.json')
    try:
        with open(config_path, 'r', encoding='utf-8') as fh:
            text = fh.read()
    except OSError as err:
        from ..config import strerror
        from ..util import colored_error
        colored_error(strerror(err))
        return 1
    try:
        data = json.loads(text)
    except ValueError as err:
        from ..util import colored_error
        colored_error('Bad JSON config %s -- %s' % (config_path, err))
        return 1
    current = data.get('metadata', {}).get('version')
    if current is None:
        from ..util import colored_error
        colored_error('Missing version in %s' % config_path)
        return 1
    try:
        cur = parse_version(current)
    except SemverError as err:
        from ..util import colored_error
        colored_error('Failed to parse %s -- %s' % (config_path, err.message))
        return 1

    bump_arg = parsed.values.get('bump')
    target = parsed.positionals[0] if parsed.positionals else None
    if bump_arg is not None:
        new = bump(bump_arg, cur)
    else:
        try:
            new = parse_version(target)
        except SemverError as err:
            raise ValueError(err.message)
    if _compare(new, cur) < 0:
        colored_warning('New version is lower than current!')
    if bump_arg is not None or target is not None:
        print('Bumping version %s to %s' % (format_version(cur),
                                            format_version(new)))
    data['metadata']['version'] = format_version(new)
    with open(config_path, 'w', encoding='utf-8') as fh:
        fh.write(json.dumps(data, indent=2))
        fh.write('\n')
    return 0


def _compare(a, b):
    ka = a[:3]
    kb = b[:3]
    if ka != kb:
        return -1 if ka < kb else 1
    pa = a[3]
    pb = b[3]
    if pa == pb:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1
    return -1 if pa < pb else 1
