"""Compares the reimplemented CLI against recorded reference output."""
import os, re, subprocess, sys

MINE = '/tmp/mine/xprogx'
CWD = '/tmp/p'

def parse_battery(path):
    out = []
    cur = None
    for line in open(path, encoding='utf-8'):
        if line.startswith('### '):
            if cur: out.append(cur)
            cur = {'cmd': line[4:].strip(), 'out': [], 'rc': None}
        elif cur is not None:
            m = re.match(r'^rc=(\d+)$', line)
            if m:
                cur['rc'] = int(m.group(1))
            else:
                cur['out'].append(line)
    if cur: out.append(cur)
    return out

def parse_b2(path):
    out = []
    cur = None
    mode = None
    for line in open(path, encoding='utf-8'):
        if line.startswith('### '):
            if cur: out.append(cur)
            cur = {'cmd': line[4:].strip(), 'out': [], 'err': [], 'rc': None}
            mode = None
        elif cur is not None:
            m = re.match(r'^rc=(\d+)$', line)
            if m:
                cur['rc'] = int(m.group(1))
                continue
            if line.strip() == 'STDOUT:':
                mode = 'out'; continue
            if line.strip() == 'STDERR:':
                mode = 'err'; continue
            if line.startswith('    '):
                cur[mode].append(line[4:])
            elif line.strip() == '':
                pass
    if cur: out.append(cur)
    return out

def run(args):
    p = subprocess.run([MINE] + args, capture_output=True, text=True, cwd=CWD)
    return p.stdout, p.stderr, p.returncode

def check(b, merged_expected):
    args = b['cmd'].split(' ')
    out, err, rc = run(args)
    got = out + err
    exp = merged_expected
    if got != exp or rc != b['rc']:
        print('=== MISMATCH: %s' % b['cmd'])
        print('--- expected (rc=%d):' % b['rc']); print(exp)
        print('--- got (rc=%d):' % rc); print(got)
        return 1
    return 0

