    fails = 0; total = 0
    for b in parse_battery('/tmp/p/gold/battery.txt'):
        total += 1
        fails += check(b, ''.join(b['out']))
    for b in parse_b2('/tmp/p/gold/b2.txt'):
        total += 1
        fails += check(b, ''.join(b['out']) + ''.join(b['err']))
    print('%d/%d passed' % (total - fails, total))
