    out['externals'] = convert(get_property(result, 'externals')) or []
    out['inline'] = convert(get_property(result, 'inline')) or []
    out['supertypes'] = convert(get_property(result, 'supertypes')) or []
    out['reserved'] = convert(get_property(result, 'reserved')) or {}
