"""Building the symbol table of a grammar."""

from ..grammar_json import content, members

END_NAME = 'end'

# Descriptive names for the characters that appear in anonymous tokens.
CHAR_NAMES = {
    '!': 'BANG', '"': 'DQUOTE', '#': 'HASH', '$': 'DOLLAR', '%': 'PERCENT',
    '&': 'AMP', "'": 'SQUOTE', '(': 'LPAREN', ')': 'RPAREN', '*': 'STAR',
    '+': 'PLUS', ',': 'COMMA', '-': 'DASH', '.': 'DOT', '/': 'SLASH',
    ':': 'COLON', ';': 'SEMI', '<': 'LT', '=': 'EQ', '>': 'GT', '?': 'QMARK',
    '@': 'AT', '[': 'LBRACK', '\\': 'BSLASH', ']': 'RBRACK', '^': 'CARET',
    '_': '_', '`': 'BACKTICK', '{': 'LBRACE', '|': 'PIPE', '}': 'RBRACE',
    '~': 'TILDE', ' ': 'SPACE', '\t': 'TAB', '\n': 'NEWLINE', '\r': 'CR',
    '0': 'ZERO', '1': 'ONE', '2': 'TWO', '3': 'THREE', '4': 'FOUR',
    '5': 'FIVE', '6': 'SIX', '7': 'SEVEN', '8': 'EIGHT', '9': 'NINE',
}


def sanitize_token(text):
    """Turns the text of an anonymous token into a symbol name suffix."""
    out = []
    for ch in text:
        if ch.isalnum() and ch.isascii():
            out.append(ch)
        else:
            out.append(CHAR_NAMES.get(ch, ''))
    return ''.join(out)


class Symbol:
    __slots__ = ('index', 'name', 'display', 'kind', 'named', 'visible',
                 'text', 'pattern', 'precedence', 'is_word')

    def __init__(self, index, name, display, kind, named, visible,
                 text=None, pattern=None, is_word=False):
        self.index = index
        self.name = name
        self.display = display
        self.kind = kind
        self.named = named
        self.visible = visible
        self.text = text
        self.pattern = pattern
        self.is_word = is_word

    def __repr__(self):
        return '<Symbol %d %s %s>' % (self.index, self.name, self.kind)


class SymbolTable:
    def __init__(self):
        self.symbols = []
        self.by_name = {}
        self.name = ''
        self.word = None

    def add(self, name, display, kind, named, visible, **kw):
        if name in self.by_name:
            return self.by_name[name]
        sym = Symbol(len(self.symbols), name, display, kind, named, visible,
                     **kw)
        self.symbols.append(sym)
        self.by_name[name] = sym
        return sym

    def error(self):
        return -1

    def end(self):
        return self.by_name[END_NAME]

    def tokens(self):
        return [s for s in self.symbols if s.kind in ('token', 'external',
                                                      'end')]

    def nonterminals(self):
        return [s for s in self.symbols if s.kind in ('nonterminal', 'aux')]


# ----------------------------------------------------------------------
# deciding which rules are tokens
# ----------------------------------------------------------------------

def is_token_rule(rule, rules, seen=None):
    """A rule is a token when its body can be lexed directly."""
    if seen is None:
        seen = set()
    kind = rule['type']
    if kind in ('STRING', 'PATTERN', 'TOKEN', 'IMMEDIATE_TOKEN'):
        return True
    if kind == 'ALIAS':
        return is_token_rule(rule['content'], rules, seen)
    if kind == 'PREC' or kind in ('PREC_LEFT', 'PREC_RIGHT', 'PREC_DYNAMIC'):
        return is_token_rule(rule['content'], rules, seen)
    if kind == 'SYMBOL':
        name = rule['name']
        if name in seen:
            return False
        if name not in rules:
            return False
        seen.add(name)
        return is_token_rule(rules[name], rules, seen)
    if kind == 'CHOICE':
        return all(is_token_rule(m, rules, seen) for m in rule['members'])
    if kind == 'SEQ':
        return all(is_token_rule(m, rules, seen) for m in rule['members'])
    return False


def is_token_like(rule):
    return rule['type'] in ('STRING', 'PATTERN', 'TOKEN', 'IMMEDIATE_TOKEN')


class Token:
    """A lexable token: either a literal string or a character pattern."""

    __slots__ = ('kind', 'text', 'pattern', 'name', 'symbol', 'immediate',
                 'precedence')

    def __init__(self, kind, text=None, pattern=None, immediate=False,
                 precedence=0):
        self.kind = kind
        self.text = text
        self.pattern = pattern
        self.immediate = immediate
        self.precedence = precedence
        self.name = None
        self.symbol = None

    def key(self):
        if self.kind == 'string':
            return ('string', self.text)
        return ('pattern', self.pattern)

    def __repr__(self):
        return 'Token(%s, %r)' % (self.kind, self.text or self.pattern)


def collect_tokens(rule, out, immediate=False, precedence=0):
    """Finds every lexable token in a rule body."""
    kind = rule['type']
    if kind == 'STRING':
        out.append(Token('string', text=rule['value'], immediate=immediate,
                         precedence=precedence))
        return
    if kind == 'PATTERN':
        out.append(Token('pattern', pattern=rule['value'],
                         immediate=immediate, precedence=precedence))
        return
    if kind == 'TOKEN':
        collect_tokens(rule['content'], out, immediate, precedence)
        return
    if kind == 'IMMEDIATE_TOKEN':
        collect_tokens(rule['content'], out, True, precedence)
        return
    if kind in ('PREC', 'PREC_LEFT', 'PREC_RIGHT', 'PREC_DYNAMIC'):
        prec = rule.get('value', 0)
        collect_tokens(rule['content'], out, immediate,
                       prec if kind != 'PREC_DYNAMIC' else 0)
        return
    if kind == 'ALIAS':
        collect_tokens(rule['content'], out, immediate, precedence)
        return
    if kind == 'CHOICE':
        for m in rule['members']:
            collect_tokens(m, out, immediate, precedence)
        return
    if kind == 'SEQ':
        for m in rule['members']:
            collect_tokens(m, out, immediate, precedence)
        return
PYEOF
echo ok"}

