"""Turning a grammar description into productions and symbols."""

from ..grammar_json import content, members, is_symbol, symbol_name
from .symbols import (SymbolTable, Token, collect_tokens, is_token_rule,
                      is_token_like, sanitize_token)

END = 'end'


class Production:
    """A production of a non terminal: a sequence of steps."""

    __slots__ = ('symbols', 'fields', 'aliases', 'dynamic_precedence',
                 'static_precedence', 'precedence_symbol')

    def __init__(self):
        self.symbols = []
        self.fields = {}       # child index -> field name
        self.aliases = {}      # child index -> (name, named)
        self.dynamic_precedence = 0
        self.static_precedence = 0
        self.precedence_symbol = None

    def copy(self):
        p = Production()
        p.symbols = list(self.symbols)
        p.fields = dict(self.fields)
        p.aliases = dict(self.aliases)
        p.dynamic_precedence = self.dynamic_precedence
        p.static_precedence = self.static_precedence
        p.precedence_symbol = self.precedence_symbol
        return p


class Grammar:
    def __init__(self, data):
        self.data = data
        self.name = data['name']
        self.word = data.get('word')
        self.table = SymbolTable()
        self.table.name = self.name
        self.productions = {}   # symbol name -> [Production]
        self.token_rules = {}   # rule name -> Token
        self.tokens = []        # list of Token in order of appearance
        self.extras = []
        self.conflicts = data.get('conflicts') or []
        self.precedences = data.get('precedences') or []
        self.inline = [i for i in (data.get('inline') or []) if i]
        self.supertypes = [s for s in (data.get('supertypes') or []) if s]
        self.reserved = data.get('reserved') or {}
        self.rules = data['rules']
        self.start_symbol = None
        self.end_symbol = None
        self.field_names = []
        self.field_ids = {}
        self.build()

    # ------------------------------------------------------------------
    def build(self):
        table = self.table
        self.end_symbol = table.add(END, END, 'end', True, False)
        rules = self.rules

        # The precedence groups define an ordering between symbols.
        self.precedence_map = {}
        for i, group in enumerate(self.precedences):
            for entry in group:
                if is_symbol(entry):
                    self.precedence_map[symbol_name(entry)] = i

        # Externals come first: they are referenced by the rules.
        for ext in self.data.get('externals') or []:
            self.add_external(ext)

        # Named rules.
        for name in rules:
            rule = rules[name]
            hidden = name.startswith('_')
            if is_token_rule(rule, rules):
                toks = []
                collect_tokens(rule, toks)
                if not toks:
                    continue
                tok = toks[0]
                sym = table.add('sym_' + name, name, 'token', not hidden,
                                True, text=tok.text, pattern=tok.pattern)
                tok.name = sym.name
                tok.symbol = sym
                self.token_rules[name] = tok
                self.add_token(tok)
            else:
                table.add('sym_' + name, name, 'nonterminal', not hidden,
                          not hidden)

        # Anonymous tokens used by the non terminal rules.
        for name in rules:
            rule = rules[name]
            if name in self.token_rules:
                continue
            toks = []
            collect_tokens(rule, toks)
            for tok in toks:
                self.add_token(tok)

        # Extra tokens (whitespace and comments).
        for ext in self.data.get('extras') or []:
            toks = []
            collect_tokens(ext, toks)
            for tok in toks:
                if tok.symbol is None:
                    self.add_token(tok)
                    if tok.symbol is None:
                        self.extra_symbols = getattr(self, 'extra_symbols', [])
            self.extras.append(ext)

        # The start symbol is the first rule that is not hidden.
        for name in rules:
            if not name.startswith('_'):
                self.start_symbol = table.by_name['sym_' + name]
                break
        if self.start_symbol is None:
            self.start_symbol = table.by_name['sym_' + rules_keys(rules)[0]]

        self.resolve_productions()

    # ------------------------------------------------------------------
    def add_token(self, tok):
        for existing in self.tokens:
            if existing.key() == tok.key():
                tok.name = existing.name
                tok.symbol = existing.symbol
                return existing
        if tok.kind == 'string':
            name = 'anon_sym_' + sanitize_token(tok.text)
            display = tok.text
            sym = self.table.add(name, display, 'token', False, True,
                                 text=tok.text)
        else:
            name = 'anon_sym_' + sanitize_token(tok.pattern) or \
                'anon_sym_pattern'
            sym = self.table.add(name, tok.pattern, 'token', False, True,
                                 pattern=tok.pattern)
        tok.name = sym.name
        tok.symbol = sym
        self.tokens.append(tok)
        return tok

    def add_external(self, ext):
        if is_symbol(ext):
            name = symbol_name(ext)
            sym = self.table.add('sym_' + name, name, 'external', True, True)
        else:
            toks = []
            collect_tokens(ext, toks)
            if toks:
                tok = toks[0]
                sym = self.add_token(tok)
                sym.kind = 'external'
                return
            sym = self.table.add('anon_sym_external', 'external', 'external',
                                 False, True)
        return sym

    # ------------------------------------------------------------------
    def resolve_productions(self):
        """Expands the rules into productions, creating aux symbols for
        repetitions."""
        table = self.table
        rules = self.rules
        self.productions = {}

        def symbol_for(name):
            sym = table.by_name.get('sym_' + name)
            if sym is not None:
                return sym
            return None

        counter = {}

        def flatten(rule, prod, in_token=False):
            """Adds the productions of `rule` to the list `out`, extending
            the partial production `prod`."""
            kind = rule['type']
            if kind == 'SEQ':
                return seq_flatten(rule['members'], prod)
            if kind == 'CHOICE':
                out = []
                for m in rule['members']:
                    out.extend(flatten(m, prod.copy()))
                return out
            if kind == 'BLANK':
                return [prod]
            if kind in ('REPEAT', 'REPEAT1'):
                aux = aux_symbol(rule, prod, kind)
                prod.symbols.append(aux.index)
                return [prod]
            if kind == 'SYMBOL':
                name = rule['name']
                sym = symbol_for(name)
                if sym is None:
                    return []
                if sym.kind in ('token', 'external'):
                    if name in self.token_rules:
                        tok = self.token_rules[name]
                        prod.symbols.append(sym.index)
                        return [prod]
                prod.symbols.append(sym.index)
                return [prod]
            if kind in ('STRING', 'PATTERN'):
                toks = []
                collect_tokens(rule, toks)
                if not toks:
                    return []
                tok = self.add_token(toks[0])
                prod.symbols.append(tok.symbol.index)
                return [prod]
            if kind == 'TOKEN' or kind == 'IMMEDIATE_TOKEN':
                toks = []
                collect_tokens(rule, toks)
                if not toks:
                    return []
                tok = self.add_token(toks[0])
                prod.symbols.append(tok.symbol.index)
                return [prod]
            if kind in ('PREC', 'PREC_LEFT', 'PREC_RIGHT', 'PREC_DYNAMIC'):
                value = rule.get('value', 0)
                if kind == 'PREC_DYNAMIC':
                    prod.dynamic_precedence = value
                else:
                    prod.static_precedence = max(prod.static_precedence,
                                                 value)
                return flatten(rule['content'], prod)
            if kind == 'FIELD':
                field_name = rule['name']
                if field_name not in self.field_ids:
                    self.field_ids[field_name] = len(self.field_names)
                    self.field_names.append(field_name)
                start = len(prod.symbols)
                out = flatten(rule['content'], prod)
                for p in out:
                    for i in range(start, len(p.symbols)):
                        if i not in p.fields:
                            p.fields[i] = field_name
                return out
            if kind == 'ALIAS':
                alias_name = rule['value']
                alias_named = rule.get('named', False)
                start = len(prod.symbols)
                out = flatten(rule['content'], prod)
                for p in out:
                    for i in range(start, len(p.symbols)):
                        if i not in p.aliases:
                            p.aliases[i] = (alias_name, alias_named)
                return out
            return [prod]

        def seq_flatten(items, prod):
            prods = [prod]
            for item in items:
                nxt = []
                for p in prods:
                    nxt.extend(flatten(item, p.copy()))
                prods = nxt
            return prods

        def aux_symbol(rule, prod, kind):
            base = prod.owner if hasattr(prod, 'owner') else ''
            name = 'aux_sym_%s_repeat1' % base
            i = counter.get(base, 0)
            i += 1
            counter[base] = i
            name = 'aux_sym_%s_repeat%d' % (base, i)
            sym = table.add(name, name[len('aux_sym_'):], 'aux', False, False)
            return sym

        for name in self.rules:
            if name in self.token_rules:
                continue
            sym = symbol_for(name)
            if sym is None:
                continue
            rule = self.rules[name]
            prods = flatten(rule, Production())
            for p in prods:
                p.owner = name
            self.productions[sym.name] = [p for p in prods]

        # The repeat aux symbols need productions of their own.
        for sym in list(self.table.symbols):
            if sym.kind == 'aux':
                name = sym.name
                rule_name = name[len('aux_sym_'):name.rindex('_repeat')]
                rule = self.rules.get(rule_name)
                if rule is None:
                    self.productions[name] = [Production()]
                    continue
                content_rule = find_repeat(rule, sym.name)
                if content_rule is None:
                    self.productions[name] = [Production()]
                    continue
                prods = flatten(content_rule, Production())
                for p in prods:
                    p.owner = rule_name
                self.productions[name] = prods


def rules_keys(rules):
    return list(rules.keys())


def find_repeat(rule, aux_name):
    """Finds the content of the repeat that produced the given aux symbol."""
    kind = rule['type']
    if kind in ('REPEAT', 'REPEAT1'):
        return rule['content']
    for key in ('members', 'content'):
        value = rule.get(key)
        if isinstance(value, list):
            for item in value:
                found = find_repeat(item, aux_name)
                if found is not None:
                    return found
        elif isinstance(value, dict):
            found = find_repeat(value, aux_name)
            if found is not None:
                return found
    return None
