{"command": "cat > /workspace/tsci/gen/tables.py <<'PYEOF'
"""LALR parse table construction."""

from .grammar import Grammar, Production

SHIFT = 0
REDUCE = 1
ACCEPT = 2
RECOVER = 3


class Action:
    __slots__ = ('kind', 'state', 'symbol', 'child_count', 'precedence',
                 'production_id', 'extra', 'repetition')

    def __init__(self, kind, state=0, symbol=0, child_count=0, precedence=0,
                 production_id=0, extra=False, repetition=False):
        self.kind = kind
        self.state = state
        self.symbol = symbol
        self.child_count = child_count
        self.precedence = precedence
        self.production_id = production_id
        self.extra = extra
        self.repetition = repetition

    def key(self):
        return (self.kind, self.state, self.symbol, self.child_count,
                self.precedence, self.production_id, self.extra,
                self.repetition)

    def __repr__(self):
        if self.kind == SHIFT:
            return 'SHIFT(%d)' % self.state
        if self.kind == REDUCE:
            return 'REDUCE(%d, %d, %d, %d)' % (self.symbol, self.child_count,
                                               self.precedence,
                                               self.production_id)
        if self.kind == ACCEPT:
            return 'ACCEPT'
        return 'RECOVER'


class State:
    __slots__ = ('index', 'core', 'items', 'terminal', 'nonterminal',
                 'expected', 'lex_state')

    def __init__(self, index, core):
        self.index = index
        self.core = core
        self.items = []
        self.terminal = {}
        self.nonterminal = {}
        self.expected = set()
        self.lex_state = 0


class Tables:
    def __init__(self, grammar):
        self.grammar = grammar
        self.states = []
        self.state_of_core = {}
        self.productions = []   # (symbol name, list of symbol indices)
        self.production_ids = {}
        self.build()

    # ------------------------------------------------------------------
    def build(self):
        grammar = self.grammar
        table = grammar.table
        # productions list with ids
        prod_id = 0
        self.prod_list = []   # (symbol index, tuple of symbol indices, prod)
        self.prod_by_symbol = {}
        for name, prods in grammar.productions.items():
            sym = table.by_name[name]
            self.prod_by_symbol[name] = []
            for p in prods:
                self.prod_list.append((sym.index, tuple(p.symbols), p))
                self.prod_by_symbol[name].append(len(self.prod_list) - 1)
        self.first = self.compute_first()

        start = grammar.start_symbol
        if start is None:
            return
        items = []
        for pi in self.prod_by_symbol[start.name]:
            items.append(Item(start.name, pi, 0, frozenset([0])))
        core = frozenset((i.nt, i.prod, i.dot) for i in items)
        state = self.add_state(core, items)
        self.closure(state)
        self.build_states()

    # ------------------------------------------------------------------
    def compute_first(self):
        first = {}

        def sym_first(sym_index):
            if sym_index in first:
                return first[sym_index]
            first[sym_index] = set()
            sym = self.grammar.table.symbols[sym_index]
            if sym.kind in ('token', 'external', 'end'):
                first[sym_index].add(sym_index)
                return first[sym_index]
            changed = True
            while changed:
                changed = False
                for pi in self.prod_by_symbol.get(sym.name, []):
                    _, syms, _ = self.prod_list[pi]
                    nullable = True
                    for s in syms:
                        sub = sym_first(s)
                        for x in sub:
                            if x not in first[sym_index]:
                                first[sym_index].add(x)
                                changed = True
                        if s in first and s in sym_first(s):
                            nullable = True
                        else:
                            nullable = False
                        break
                    if nullable and not syms:
                        # epsilon production: mark by including -2
                        if -2 not in first[sym_index]:
                            first[sym_index].add(-2)
                            changed = True
            return first[sym_index]

        for i, sym in enumerate(self.grammar.table.symbols):
            if sym.kind in ('nonterminal', 'aux'):
                sym_first(i)
        return first

    def first_of_seq(self, syms, start, offset, lookahead):
        """The first set of syms[offset:] followed by lookahead."""
        out = set()
        for i in range(offset, len(syms)):
            s = syms[i]
            sub = self.first.get(s, {s})
            for x in sub:
                if x != -2:
                    out.add(x)
            if -2 not in sub:
                return out
        out |= set(lookahead)
        return out

    # ------------------------------------------------------------------
    def add_state(self, core, items=None):
        if core in self.state_of_core:
            return self.state_of_core[core]
        state = State(len(self.states), core)
        if items is not None:
            state.items = list(items)
        self.states.append(state)
        self.state_of_core[core] = state
        return state

    def closure(self, state):
        work = list(state.items)
        seen = set((i.nt, i.prod, i.dot, i.lookahead) for i in state.items)
        while work:
            item = work.pop()
            syms = self.prod_list[item.prod][1]
            if item.dot >= len(syms):
                continue
            sym_index = syms[item.dot]
            sym = self.grammar.table.symbols[sym_index]
            if sym.kind not in ('nonterminal', 'aux'):
                continue
            lookahead = self.first_of_seq(syms, item.lookahead,
                                          item.dot + 1, item.lookahead)
            if not lookahead:
                lookahead = set(item.lookahead)
            for pi in self.prod_by_symbol.get(sym.name, []):
                new = Item(sym.name, pi, 0, frozenset(lookahead))
                key = (new.nt, new.prod, new.dot, new.lookahead)
                if key in seen:
                    continue
                seen.add(key)
                state.items.append(new)
                work.append(new)

    def build_states(self):
        queue = [self.states[0]]
        while queue:
            state = queue.pop(0)
            # group the items by symbol at the dot
            groups = {}
            for item in state.items:
                syms = self.prod_list[item.prod][1]
                if item.dot >= len(syms):
                    continue
                groups.setdefault(syms[item.dot], []).append(item)
            for sym_index, items in groups.items():
                new_items = []
                for item in items:
                    new_items.append(Item(item.nt, item.prod, item.dot + 1,
                                          item.lookahead))
                core = frozenset((i.nt, i.prod, i.dot) for i in new_items)
                target = self.state_of_core.get(core)
                if target is None:
                    target = self.add_state(core)
                    target.items = new_items
                    self.closure(target)
                    queue.append(target)
                else:
                    merged = False
                    for item in new_items:
                        for existing in target.items:
                            if (existing.nt == item.nt and
                                    existing.prod == item.prod and
                                    existing.dot == item.dot):
                                if not set(item.lookahead) <= \
                                        set(existing.lookahead):
                                    existing.lookahead = frozenset(
                                        set(existing.lookahead) |
                                        set(item.lookahead))
                                    merged = True
                                break
                        else:
                            target.items.append(item)
                            merged = True
                    if merged:
                        self.closure(target)
                        queue.append(target)
                sym = self.grammar.table.symbols[sym_index]
                if sym.kind in ('token', 'external', 'end'):
                    state.terminal.setdefault(sym_index, [])
                    repetition = False
                    for item in items:
                        if item.nt == 'aux' or True:
                            pass
                    state.terminal[sym_index].append(Action(
                        SHIFT, state=target.index))
                    state.expected.add(sym_index)
                else:
                    state.nonterminal[sym_index] = target.index
            # reductions
            for item in state.items:
                syms = self.prod_list[item.prod][1]
                if item.dot < len(syms):
                    continue
                nt_index = self.grammar.table.by_name[item.nt].index
                _, _, prod = self.prod_list[item.prod]
                prod_id = item.prod
                action = Action(REDUCE, symbol=nt_index,
                                child_count=len(syms),
                                precedence=prod.static_precedence,
                                production_id=prod_id)
                for lookahead in item.lookahead:
                    if lookahead == -2:
                        continue
                    actions = state.terminal.setdefault(lookahead, [])
                    if any(a.kind == REDUCE and
                           a.symbol == action.symbol and
                           a.child_count == action.child_count and
                           a.production_id == action.production_id
                           for a in actions):
                        continue
                    actions.append(action)
                    state.expected.add(lookahead)
        self.resolve_conflicts()


class Item:
    __slots__ = ('nt', 'prod', 'dot', 'lookahead')

    def __init__(self, nt, prod, dot, lookahead):
        self.nt = nt
        self.prod = prod
        self.dot = dot
        self.lookahead = lookahead

    def key(self):
        return (self.nt, self.prod, self.dot, self.lookahead)
PYEOF
echo ok"}

