def find_prec_kind(rule, depth=0):
    if rule is None or depth > 8:
        return None
    kind = rule.get('type')
    if kind == 'PREC_LEFT':
        return 'left'
    if kind == 'PREC_RIGHT':
        return 'right'
    if kind in ('PREC', 'PREC_DYNAMIC'):
        return None
    for key in ('members', 'content'):
        value = rule.get(key)
        if isinstance(value, list):
            for item in value:
                found = find_prec_kind(item, depth + 1)
                if found:
                    return found
        elif isinstance(value, dict):
            found = find_prec_kind(value, depth + 1)
            if found:
                return found
    return None""")
