# A node in the DFA: transitions from character ranges to other nodes.
class Node:
    __slots__ = ('index', 'transitions', 'accept', 'skip', 'eof')

    def __init__(self, index):
        self.index = index
        self.transitions = []   # (start, end, target, skip)
        self.accept = None      # symbol index
        self.skip = False
        self.eof = None


class DFA:
    def __init__(self):
        self.nodes = []
        self.start = self.new_node()

    def new_node(self):
        node = Node(len(self.nodes))
        self.nodes.append(node)
        return node


