"""Compiles JavaScript regular expressions into an NFA over character
ranges, which is what the reference implementation's lexer uses."""

import sre_parse
import sre_constants

MAX_CHAR = 0x10FFFF

CATEGORY_RANGES = {
    'CATEGORY_DIGIT': [(48, 57)],
    'CATEGORY_NOT_DIGIT': [(0, 47), (58, MAX_CHAR)],
    'CATEGORY_SPACE': [(9, 13), (32, 32)],
    'CATEGORY_NOT_SPACE': [(0, 8), (14, 31), (33, MAX_CHAR)],
    'CATEGORY_WORD': [(48, 57), (65, 90), (95, 95), (97, 122)],
    'CATEGORY_NOT_WORD': [(0, 47), (58, 64), (91, 94), (96, 96),
                         (123, MAX_CHAR)],
    'CATEGORY_LINEBREAK': [(10, 10), (13, 13)],
    'CATEGORY_NON_LINEBREAK': [(0, 9), (11, 12), (14, MAX_CHAR)],
}


class NFA:
    def __init__(self):
        self.transitions = []   # state -> list of (kind, data, target)
        self.accept = {}        # state -> token index

    def new_state(self):
        self.transitions.append([])
        return len(self.transitions) - 1

    def add(self, state, kind, data, target):
        self.transitions[state].append((kind, data, target))

    def epsilon(self, state, target):
        self.add(state, 'eps', None, target)


def compile_pattern(pattern, flags=0):
    """Returns an NFA with a single start state (state 0) whose language is
    the pattern."""
    nfa = NFA()
    start = nfa.new_state()
    try:
        parsed = sre_parse.parse(pattern, flags)
    except (sre_constants.error, Exception):
        # fall back to a literal interpretation
        end = add_literal(nfa, start, pattern)
        nfa.accept[end] = 0
        return nfa, start
    end = build(nfa, start, parsed)
    nfa.accept[end] = 0
    return nfa, start


def build(nfa, state, node):
    op = node[0]
    if op == sre_parse.LITERAL:
        target = nfa.new_state()
        nfa.add(state, 'char', [(node[1], node[1])], target)
        return target
    if op == sre_parse.NOT_LITERAL:
        target = nfa.new_state()
        nfa.add(state, 'char', [(0, node[1] - 1), (node[1] + 1, MAX_CHAR)],
                target)
        return target
    if op == sre_parse.ANY:
        target = nfa.new_state()
        nfa.add(state, 'char', [(0, 9), (11, MAX_CHAR)], target)
        return target
    if op == sre_parse.IN:
        ranges = in_ranges(node[1])
        target = nfa.new_state()
        nfa.add(state, 'char', ranges, target)
        return target
    if op == sre_parse.BRANCH:
        _, branches = node[1]
        ends = []
        for branch in branches:
            ends.append(build(nfa, state, branch))
        join = nfa.new_state()
        for e in ends:
            nfa.epsilon(e, join)
        return join
    if op == sre_parse.SUBPATTERN:
        group, add_flags, del_flags, pattern = node[1]
        return build(nfa, state, pattern)
    if op == sre_parse.MAX_REPEAT or op == sre_parse.MIN_REPEAT:
        minimum, maximum, pattern = node[1]
        current = state
        for _ in range(minimum):
            current = build(nfa, current, pattern)
        if maximum == sre_parse.MAXREPEAT:
            # (x)* : loop back
            loop_start = current
            end = build(nfa, current, pattern)
            nfa.epsilon(end, loop_start)
            nfa.epsilon(loop_start, end)
            nfa.epsilon(state, loop_start)
            return loop_start
        else:
            ends = [current]
            cur = current
            for _ in range(maximum - minimum):
                nxt = build(nfa, cur, pattern)
                ends.append(nxt)
                cur = nxt
