    """Subset construction over one or more NFAs (one per token)."""

    def __init__(self, patterns):
        self.nfas = []
        self.start_states = []
        for pattern, flags in patterns:
            nfa, start = compile_pattern(pattern, flags)
            self.nfas.append(nfa)
            self.start_states.append(start)
        self.states = {}
        self.order = []

    def start_set(self):
        out = set()
        for i, start in enumerate(self.start_states):
            out |= epsilon_closure(self.nfas[i], {start})
        return frozenset((i, s) for i, s in out)

    def transitions(self, state_set):
        """Returns a list of (range, next_state_set)."""
        by_char = {}
        for token_index, state in state_set:
            nfa = self.nfas[token_index]
            for kind, data, target in nfa.transitions[state]:
                if kind != 'char':
                    continue
                for lo, hi in data:
                    by_char.setdefault((lo, hi), set()).add(
