    """Returns an NFA with a single start state (state 0) whose language is
    the pattern."""
    nfa = NFA()
    start = nfa.new_state()
    try:
        parsed = sre_parse.parse(pattern, flags)
    except (sre_constants.error, Exception):
        # fall back to a literal interpretation
        end = add_literal(nfa, start, pattern)
        nfa.accept[end] = 0
        return nfa, start
    end = build(nfa, start, parsed)
    nfa.accept[end] = 0
    return nfa, start


