"""Generating node-types.json."""

import json

from ..grammar_json import is_symbol, symbol_name


def generate_node_types(grammar):
    entries = []
    for sym in grammar.table.symbols:
        if not sym.visible:
            continue
        info = {'type': sym.display, 'named': sym.named}
        if sym is grammar.start_symbol:
            info['root'] = True
        if sym.kind in ('nonterminal', 'aux'):
            children, fields = node_children(grammar, sym)
            info['fields'] = fields
            if children is not None:
                info['children'] = children
        entries.append(info)
    return json.dumps(entries, indent=2)


def node_children(grammar, sym):
    """Computes the children and fields of a non terminal symbol."""
    prods = grammar.productions.get(sym.name) or []
    types = {}
    fields = {}
    multiple = False
    required = None
    for prod in prods:
        seen, prod_fields, prod_required = production_children(grammar, prod)
        for child, field_name in seen:
            types[(child.display, child.named)] = child
            if field_name:
                entry = fields.setdefault(field_name, {'multiple': False,
                                                       'required': False,
                                                       'types': {}})
                entry['types'][(child.display, child.named)] = child
        multiple = multiple or len(seen) > 1
        if required is None:
            required = prod_required
        else:
            required = required and prod_required
    if not types:
        return None, {}
    children = {
        'multiple': multiple,
        'required': bool(required),
        'types': [type_info(c) for _, c in sorted(types.items(),
                                                  key=lambda item: (
                                                      item[1].display,
                                                      not item[1].named))],
    }
    if not any(t['named'] for t in children['types']) and \\
            len(children['types']) == 1 and not multiple:
        return None, {}
    field_out = {}
    for name, entry in fields.items():
        field_out[name] = {
            'multiple': len(entry['types']) > 1,
            'required': True,
            'types': [type_info(c) for _, c in
                      sorted(entry['types'].items(),
                             key=lambda item: (item[1].display,
                                               not item[1].named))],
        }
    return children, field_out


def type_info(sym):
    return {'type': sym.display, 'named': sym.named}


def production_children(grammar, prod):
    """The visible children of a production, in order."""
    out = []
    fields = []
    required = True
    for index, symbol_index in enumerate(prod.symbols):
        sym = grammar.table.symbols[symbol_index]
        field_name = prod.fields.get(index)
        for child, child_field in expand(grammar, sym, field_name):
            out.append((child, child_field))
            fields.append(child_field)
        if sym.kind == 'aux':
            required = False
    return out, fields, required and bool(out)


def expand(grammar, sym, field_name):
    """Yields the visible symbols that a symbol produces."""
    if sym.visible:
        yield sym, field_name
        return
    if sym.kind == 'aux':
        for prod in grammar.productions.get(sym.name) or []:
            for index, symbol_index in enumerate(prod.symbols):
                child = grammar.table.symbols[symbol_index]
                for item, item_field in expand(grammar, child, field_name):
                    yield item, item_field or field_name
        return
    if sym.kind == 'nonterminal':
        for prod in grammar.productions.get(sym.name) or []:
            for index, symbol_index in enumerate(prod.symbols):
                child = grammar.table.symbols[symbol_index]
                for item, item_field in expand(grammar, child, field_name):
                    yield item, item_field or field_name
        return
