"""Implementation of `tree-sitter parse`."""

import os
import sys
import time

from ..util import colored_error
from ..language import load_language, LanguageError


def run(parsed):
    paths = collect_paths(parsed)
    if not paths:
        colored_error('No files were found at or matched by the provided '
                      'pathname/glob')
        return 1
    quiet = 'quiet' in parsed.flags
    show_time = 'time' in parsed.flags
    no_ranges = 'no-ranges' in parsed.flags
    show_stat = 'stat' in parsed.flags
    had_error = False
    for path in paths:
        try:
            language = load_language(parsed, path)
        except LanguageError as err:
            colored_error('Failed to load language for path "%s"' % path)
            if err.message:
                sys.stderr.write('\nCaused by:\n    %s\n' % err.message)
            return 1
        try:
            with open(path, 'rb') as fh:
                source = fh.read()
        except OSError as err:
            colored_error('Failed to read %s' % path)
            return 1
        text = decode(source, parsed.values.get('encoding'))
        started = time.time()
        tree = language.parse(text)
        elapsed = time.time() - started
        if tree.has_error:
            had_error = True
        if not quiet:
            sys.stdout.write(tree.sexpr(no_ranges=no_ranges) + '\n')
        if had_error or show_stat or show_time:
            size = len(source)
            rate = size / (elapsed * 1000) if elapsed > 0 else 0
            sys.stdout.write('%s\tParse: %8.2f ms\t%s\t%s\n' % (
                path, elapsed * 1000, format_rate(rate),
                tree.sexpr(no_ranges=True)))
    return 1 if had_error else 0


def format_rate(rate):
    return '%7d bytes/ms' % int(rate)


def collect_paths(parsed):
    paths = list(parsed.positionals)
    paths_file = parsed.values.get('paths')
    if paths_file:
        try:
            with open(paths_file) as fh:
                for line in fh:
                    line = line.strip()
                    if line:
                        paths.append(line)
        except OSError:
            pass
    return paths


def decode(source, encoding):
    if encoding == 'utf16-le':
        return source.decode('utf-16-le', errors='replace')
    if encoding == 'utf16-be':
        return source.decode('utf-16-be', errors='replace')
    return source.decode('utf-8', errors='replace')
