"""Locating and loading the language for a file."""

import os
import re

from .config import load_config, config_dir, cache_dir
from .grammar_load import load as load_grammar_text
from .grammar_json import parse_grammar, SchemaError
from .gen.grammar import Grammar
from .gen.build_tables import Emitted
from .util import colored_warning


class LanguageError(Exception):
    def __init__(self, message=''):
        super().__init__(message)
        self.message = message


class Language:
    def __init__(self, name, grammar, tables):
        self.name = name
        self.grammar = grammar
        self.tables = tables

    def parse(self, text):
        from .runtime.parser import Parser
        parser = Parser(self.tables.tables, self.tables.lex_states)
        return Tree(parser.parse(text), self)


class Tree:
    def __init__(self, root, language):
        self.root = root
        self.language = language

    @property
    def has_error(self):
        return any_errors(self.root)

    def sexpr(self, no_ranges=False):
        out = []
        write_node(self.root, out, 0, no_ranges)
        return '\n'.join(out)


def any_errors(node):
    if node.symbol is None:
        return True
    if node.is_missing:
        return True
    return any(any_errors(c) for c in node.children)


def position_of(text, offset):
    """Returns (row, column) for a byte offset."""
    row = text.count('\n', 0, offset)
    if row == 0:
        return 0, offset
    last = text.rfind('\n', 0, offset)
    return row, offset - last - 1


def write_node(node, out, depth, no_ranges):
    if node.symbol is not None and not node.symbol.visible:
        for child in node.children:
            write_node(child, out, depth, no_ranges)
        return
    pad = '  ' * depth
    name = node.symbol.display if node.symbol is not None else 'ERROR'
    if node.is_missing:
        name = 'MISSING'
    if node.field:
        name = '%s: %s' % (node.field, name)
    if no_ranges:
        out.append('%s(%s)' % (pad, name))
        for child in node.children:
            write_node(child, out, depth + 1, no_ranges)
        return
    start = node.start
    end = node.end
    out.append('%s(%s [%d, %d] - [%d, %d]' % (pad, name, 0, start, 0, end))
    if not node.children:
        out[-1] += ')'
    else:
        for child in node.children:
            write_node(child, out, depth + 1, no_ranges)
        out[-1] = out[-1] + ')'
