"""The query language: parsing patterns and matching them against a tree."""

import re


class QueryError(Exception):
    def __init__(self, message):
        super().__init__(message)
        self.message = message


class Capture:
    __slots__ = ('name', 'node')

    def __init__(self, name, node):
        self.name = name
        self.node = node


class NodePattern:
    __slots__ = ('kind', 'name', 'children', 'captures', 'field', 'quantifier',
                 'text', 'predicate')

    def __init__(self, kind, name=None, text=None):
        self.kind = kind          # 'node', 'text', 'wildcard'
        self.name = name
        self.text = text
        self.children = []
        self.captures = []
        self.field = None
        self.quantifier = None
        self.predicate = None


class Query:
    def __init__(self, text):
        self.patterns = []
        self.captures = set()
        self.parse(text)

    # ------------------------------------------------------------------
    def parse(self, text):
        tokens = tokenize(text)
        pos = [0]
        while pos[0] < len(tokens):
            tok = tokens[pos[0]]
            if tok[0] == 'pred':
                # a predicate applies to the previous pattern
                if self.patterns:
                    self.patterns[-1].predicate = read_predicate(tokens, pos)
                continue
            pattern = parse_pattern(tokens, pos, self)
            if pattern is None:
                break
            if pattern.predicate is not None or pattern.captures or \\
                    pattern.children or pattern.kind != 'wildcard':
                self.patterns.append(pattern)
            pos[0] += 1

    # ------------------------------------------------------------------
    def matches(self, tree):
        out = []
        for pattern in self.patterns:
            for node in walk(tree.root):
                captures = []
                if match_pattern(pattern, node, captures, tree):
                    if pattern.predicate and not \\
                            check_predicate(pattern.predicate, captures,
                                            tree):
                        continue
                    out.append((pattern, captures))
        return out


def tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch in ' \t\r\n':
            i += 1
            continue
        if ch == ';':
            while i < n and text[i] != '\n':
                i += 1
            continue
        if ch == '(' or ch == ')':
            tokens.append(('punct', ch))
            i += 1
            continue
        if ch == '"':
            j = i + 1
            buf = []
            while j < n and text[j] != '"':
                if text[j] == '\\\\':
                    buf.append(text[j + 1])
                    j += 2
                    continue
                buf.append(text[j])
                j += 1
            tokens.append(('text', ''.join(buf)))
            i = j + 1
            continue
        if ch == '[':
            j = text.index(']', i)
            tokens.append(('class', text[i + 1:j]))
            i = j + 1
            continue
        if ch == '@':
            j = i + 1
            while j < n and (text[j].isalnum() or text[j] in '_.-'):
                j += 1
            tokens.append(('capture', text[i + 1:j]))
            i = j
            continue
        if ch == '#':
            j = text.index('(', i) if '(' in text else n
            tokens.append(('pred', text[i:j].strip()))
            i = j
            continue
        if ch == '_' or ch.isalpha():
            j = i
            while j < n and (text[j].isalnum() or text[j] in '_-.'):
                j += 1
            tokens.append(('ident', text[i:j]))
            i = j
            continue
        if ch in '?*+':
            tokens.append(('quant', ch))
            i += 1
            continue
        if ch == '.':
            tokens.append(('dot', '.'))
            i += 1
            continue
        i += 1
    return tokens


def parse_pattern(tokens, pos, query):
    tok = tokens[pos[0]]
    if tok[0] == 'punct' and tok[1] == '(':
        pos[0] += 1
        name = None
        kind = 'node'
        if pos[0] < len(tokens):
            nxt = tokens[pos[0]]
            if nxt[0] == 'ident':
                name = nxt[1]
                pos[0] += 1
            elif nxt[0] == 'dot':
                kind = 'wildcard'
                pos[0] += 1
        pattern = NodePattern(kind, name)
        while pos[0] < len(tokens):
            tok = tokens[pos[0]]
            if tok[0] == 'punct' and tok[1] == ')':
                pos[0] += 1
                break
            if tok[0] == 'capture':
                pattern.captures.append(tok[1])
                query.captures.add(tok[1])
                pos[0] += 1
                continue
            if tok[0] == 'ident':
                field = tok[1]
                pos[0] += 1
                if pos[0] < len(tokens) and tokens[pos[0]][0] == 'punct' and \\
                        tokens[pos[0]][1] == ':':
                    pos[0] += 1
                    child = parse_pattern(tokens, pos, query)
                    if child is not None:
                        child.field = field
                        pattern.children.append(child)
                else:
                    child = NodePattern('wildcard')
                    child.field = field
                    pattern.children.append(child)
                continue
            if tok[0] == 'text':
                child = NodePattern('text', text=tok[1])
                pos[0] += 1
                pattern.children.append(child)
                continue
            if tok[0] == 'quant':
                if pattern.children:
                    pattern.children[-1].quantifier = tok[1]
                pos[0] += 1
                continue
            if tok[0] == 'pred':
                pattern.predicate = read_predicate(tokens, pos)
                continue
            child = parse_pattern(tokens, pos, query)
            if child is None:
                break
            pattern.children.append(child)
        return pattern
    if tok[0] == 'text':
        pos[0] += 1
        pattern = NodePattern('text', text=tok[1])
        while pos[0] < len(tokens) and tokens[pos[0]][0] == 'capture':
            pattern.captures.append(tokens[pos[0]][1])
            query.captures.add(tokens[pos[0]][1])
            pos[0] += 1
        return pattern
    if tok[0] == 'ident':
        pos[0] += 1
        pattern = NodePattern('node', name=tok[1])
        while pos[0] < len(tokens) and tokens[pos[0]][0] == 'capture':
            pattern.captures.append(tokens[pos[0]][1])
            query.captures.add(tokens[pos[0]][1])
            pos[0] += 1
        return pattern
    if tok[0] == 'capture':
        pos[0] += 1
        pattern = NodePattern('capture', name=tok[1])
        query.captures.add(tok[1])
        return pattern
    return None


def read_predicate(tokens, pos):
    """Reads a predicate like `(#eq? @cap "text")`."""
    head = tokens[pos[0]][1]
    pos[0] += 1
    args = []
    while pos[0] < len(tokens):
        tok = tokens[pos[0]]
        if tok[0] == 'punct' and tok[1] == ')':
            pos[0] += 1
            break
        if tok[0] == 'capture':
            args.append('@' + tok[1])
            pos[0] += 1
            continue
        if tok[0] == 'text':
            args.append(tok[1])
            pos[0] += 1
            continue
        pos[0] += 1
    return (head, args)


def check_predicate(predicate, captures, tree):
    head, args = predicate
    by_name = {c.name: c for c in captures}
    if head in ('#eq?', '#any-eq?'):
        node = by_name.get(args[0][1:])
        return node is not None and text_of(node.node, tree) == args[1]
    if head in ('#not-eq?', '#any-not-eq?'):
        node = by_name.get(args[0][1:])
        return node is not None and text_of(node.node, tree) != args[1]
    if head in ('#match?', '#any-match?'):
        node = by_name.get(args[0][1:])
        return node is not None and \\
            re.match(args[1], text_of(node.node, tree)) is not None
    if head in ('#not-match?', '#any-not-match?'):
        node = by_name.get(args[0][1:])
        return node is not None and \\
            re.match(args[1], text_of(node.node, tree)) is None
    if head == '#any-of?':
        node = by_name.get(args[0][1:])
        return node is not None and text_of(node.node, tree) in args[1:]
    if head == '#not-any-of?':
        node = by_name.get(args[0][1:])
        return node is not None and text_of(node.node, tree) not in args[1:]
    if head == '#is-not?':
        return True
    return True


def text_of(node, tree):
    return tree.text[node.start:node.end]


def match_pattern(pattern, node, captures, tree):
    if pattern.kind == 'wildcard':
        pass
    elif pattern.kind == 'node':
        if node.symbol is None or node.symbol.display != pattern.name:
            return False
    elif pattern.kind == 'text':
        if node.symbol is None or node.symbol.kind not in ('token',
                                                           'external'):
            return False
        if node.symbol.display != pattern.text:
            return False
    elif pattern.kind == 'capture':
        captures.append(Capture(pattern.name, node))
        return True
    if node.symbol is not None:
        for name in pattern.captures:
            captures.append(Capture(name, node))
    if not pattern.children:
        return True
    children = [c for c in node.children]
    idx = 0
    for child in pattern.children:
        if child.field:
            candidates = [c for c in children if c.field == child.field]
        else:
            candidates = children
        matched = False
        for cand in candidates:
            sub = []
            if match_pattern(child, cand, sub, tree):
                captures.extend(sub)
                matched = True
                break
        if not matched:
            if child.quantifier in ('?', '*'):
                continue
            return False
    return True


def walk(node):
    yield node
    for child in node.children:
        yield from walk(child)
