    def parse(self, text):
        tokens = tokenize(text)
        pos = [0]
        while pos[0] < len(tokens):
            tok = tokens[pos[0]]
            if tok[0] == 'pred':
                # a predicate applies to the previous pattern
                if self.patterns:
                    self.patterns[-1].predicate = read_predicate(tokens, pos)
                continue
            pattern = parse_pattern(tokens, pos, self)
            if pattern is None:
                break
            if pattern.predicate is not None or pattern.captures or \\
                    pattern.children or pattern.kind != 'wildcard':
                self.patterns.append(pattern)
            pos[0] += 1

